INSERT INTO public.paragraph_questions (id, category, difficulty, grade_band, passage, question, options, correct_index, explanation, is_active, source, archived_at, content_fingerprint) VALUES
  ('v2-4-5-main_idea-01', 'main_idea', 'medium', '4-5', 'Mahalle çocukları ilkbaharda küçük göletin çevresinde çöp biriktiğini fark etti. Önce yalnızca görünen çöpleri topladılar; sonra hangi günlerde daha çok atık biriktiğini gözlemleyip yakındaki dükkânlara geri dönüşüm kutusu koymayı önerdiler. Birkaç hafta sonra göletin çevresi daha temiz kaldı ve ördekler için ayrılan alanı korumak kolaylaştı. Sonraki haftalarda çocuklar kutuların doluluk durumunu kontrol edip gerekli değişiklikleri yaptılar.', 'Gölet çevresindeki değişimler birlikte düşünüldüğünde parçanın ana düşüncesi aşağıdakilerden hangisidir?', '["Gölet çevresindeki ördeklerin sayısı her mevsim aynı kalır ve değişmez.","Çöpleri toplamak, gözlem yapılmadan da sorunu çözmeye yeter.","Bir çevre sorununu çözmek, gözlem ve ortak çabayla daha kalıcı hâle gelebilir.","Çocukların çevre çalışması, ilkbaharla sınırlı kalmıştır.","Geri dönüşüm kutuları, düzenli bakım yapılmasa bile çevreyi temiz tutabilir."]'::jsonb, 2, 'C seçeneği, ilk temizlikten sonra gözlem yapılmasını ve ortak çözüm kurulmasını birlikte kapsar. A seçeneği ayrıntıyı, E seçeneği ise sonucu gereğinden fazla genişletir.', true, 'migration', NULL, '6d610a49e2630ecbace3ebce9ba33e406578c648401201ab44a267dc671c3054'),
  ('v2-4-5-supporting_idea-01', 'supporting_idea', 'easy', '4-5', 'Elif, evdeki çocuk kitaplarını yaşına göre ayırıp apartmanın girişindeki değiş tokuş rafına yerleştirdi. Rafın yanına, alınan kitabın yerine başka bir kitap bırakılabileceği yazıldı. İlk hafta birkaç komşu yalnızca kitap almakla kaldı; sonraki hafta çocuklar okudukları kitapları geri getirip rafın yanına kısa öneriler ekledi. Böylece raf, kitapların el değiştirdiği ve okuma önerilerinin paylaşıldığı bir köşeye dönüştü.', 'Değiş tokuş rafının kullanımıyla ilgili parçada hangi bilgiye yer verilmiştir?', '["Rafı ilk hafta yetişkinler düzenlemiştir.","Çocuklar okudukları kitaplar için kısa öneriler yazmıştır.","Kitaplar yaşlarına göre ayrılmış, ancak değiş tokuş yapılmamıştır.","Komşular önerilerini kitaplardan bağımsız olarak paylaşmıştır.","Raf, kitap alınmadan önce başka bir yere taşınmıştır."]'::jsonb, 1, 'B seçeneği, çocukların okudukları kitapları geri getirip öneri eklediği açık bilgisine dayanır. Diğer seçenekler metindeki uygulamayla çelişir veya desteklenmez.', true, 'migration', NULL, '998b745a7f2abef8e602b21cc46a792fe5f0f11f6975fcff48b178911adb1758'),
  ('v2-4-5-inference-01', 'inference', 'hard', '4-5', 'Aile, piknik için göl kıyısına gitmek üzereyken rüzgârın güçlendiğini fark etti. Babası, masayı ağaçların altına kurmak yerine açık alandaki taş zemini seçti; çocuklar da uçabilecek kâğıtları çantaya koydu. Öğleden sonra rüzgâr azalınca örtüyü çimenlere serdiler. Günün planı değişmiş olsa da aile, hava durumunu izleyerek eşyaların ve çevrenin zarar görmesini önledi.', 'Ailenin piknik sırasındaki kararlarından hareketle aşağıdaki yargılardan hangisine ulaşılabilir?', '["Aile, planını hava koşullarına göre değiştirmeyi göze almıştır.","Çocuklar açık havada piknik yapmaktan vazgeçmiştir.","Taş zemin, rüzgâr sırasında çimenlerden daha güvenli olduğu için seçilmiştir.","Rüzgâr öğleden sonra da güçlenmiş ve ailenin piknikten dönmesine yol açmıştır.","Piknik eşyaları hazırlıksız çıkıldığı için eksik kalmış, plan bu yüzden değişmiştir."]'::jsonb, 0, 'A seçeneği, rüzgâr varken yerin ve eşyaların değiştirilmesi ile daha sonra planın sürdürülmesini birlikte yorumlar. C seçeneği ise tek bir günü anlatan kararı her duruma geneller.', true, 'migration', NULL, 'd5869a04b4a247cf14322d5d9c46a6f38505bded7b3d02b3cd4dc4230ffac59a'),
  ('v2-4-5-completion-01', 'completion', 'hard', '4-5', 'Deniz, mahalle fırınının önündeki su kabının her akşam boşaldığını fark etti. Önce kabın küçük olduğunu düşündü; daha büyük bir kap koyunca su yine kısa sürede bitti. Sonra sıcak günlerde çevredeki kedilerin daha sık uğradığını gözlemledi ve kabı gölgeye taşıdı. Su artık daha uzun süre kaldı, fakat sabahları kabın çevresinde izler görmeye devam etti. _____', 'Deniz''in gözlemlerinden sonra paragrafın düşünce akışına uygun cümle aşağıdakilerden hangisidir?', '["Su kabının hacmini artırmanın, konumu değiştirmekten daha belirleyici olduğunu düşündü.","Kedilerin suya ne zaman ulaştığını bilmenin, kabın yerini değiştirmeye gerek bırakacağını savundu.","Su kabında doğru çözüm için hacim, konum ve zamanı birlikte düşünmek gerektiğini anladı.","Sıcak günlerde görülen izlerin, kapta kalan su miktarını açıklamadığını düşündü.","Kabın yerini değiştirdiğinde suyun azalmasının nedenini kesin olarak bulduğuna karar verdi."]'::jsonb, 2, 'C seçeneği, kabın büyüklüğü, bulunduğu yer ve kedilerin kullanım zamanı arasındaki ilişkiyi birlikte kurar. A ve B seçenekleri bu etkenlerden birini öne çıkarıp diğer gözlemleri daraltır; E ise gözlemlerin izin verdiğinden daha kesin bir sonuç bildirir.', true, 'migration', NULL, 'c34c4f352490c170d4ffda27ff5fd173e9bc8e713e915a21923a6151753466ab'),
  ('v2-4-5-flow-01', 'flow', 'hard', '4-5', '(I) Gölet suyunun berraklığı farklı günlerde ölçüldü. (II) Suyun içindeki yaprak ve plastik parçaları türlerine göre ayrıldı. (III) Yağmurdan sonraki ölçümler, kuru günlerdeki sonuçlarla karşılaştırıldı. (IV) Ziyaretçilerin gölet çevresinde dinlenmek için seçtiği noktalar işaretlendi. (V) Elde edilen notlara göre temizlik günlerinde hangi bölümlere öncelik verileceği belirlendi.', 'Gölet suyunun incelenme sürecini anlatan numaralı cümlelerden hangisi düşünce akışını bozmaktadır?', '["I","II","III","V","IV"]'::jsonb, 4, 'IV. cümle ziyaretçilerin dinlenme tercihine geçer; I, II, III ve V ise suyun durumunu ölçüp temizlik kararına bağlayan bir inceleme zinciri oluşturur.', true, 'migration', NULL, 'b90a0c71ed457f107f7b2d817cfcdfe43127e32943fdc2d7c8853a2b04067ee9'),
  ('v2-8-main_idea-01', 'main_idea', 'medium', '8', 'Eski pazar yerinin yenilenmesi planlanırken belediye yalnızca binaların dış görünüşünü değiştirmedi. Esnafın hangi saatlerde yoğunluk yaşadığını, yayaların nerelerde durduğunu ve çevredeki tarihî yapıların hangi açılardan görüldüğünü inceledi. Yeni düzenlemede oturma alanları bu gözlemlere göre yerleştirildi; bazı cephelerde eski ayrıntılar korundu. Yeni düzenlemede sabah alışverişine gelenlerle akşam dinlenmek isteyenler alanı farklı biçimlerde kullanabildi.', 'Pazar yerinin yenilenmesini anlatan bu parçanın bütünü için aşağıdaki yargılardan hangisi söylenebilir?', '["Bir alanı yenilemek, geçmişini koruyarak bugünkü kullanıma uyarlamaktır.","Eski yapıların tamamı yeni binalarla değiştirilmelidir.","Pazar yerlerinin düzenlenmesinde esnafın görüşü tek başına belirleyicidir.","Tarihî ayrıntılar günlük kullanımı çoğu durumda zorlaştırır.","Yayaların durduğu yerler, şehir planlamasında ikincil bir ayrıntıdır."]'::jsonb, 0, 'A seçeneği, kullanım gözlemleriyle tarihî ayrıntıların aynı tasarım kararında birleştirilmesini özetler. C ve D seçenekleri parçadaki kapsamı daraltır veya tersine çevirir.', true, 'migration', NULL, '984ebe9c3ac76cf3a03aee5e3389aed3289fb2ad6766e12797978321d5372fcb'),
  ('v2-8-supporting_idea-01', 'supporting_idea', 'easy', '8', 'Bir öğrenci podcast hazırlarken konuşmanın tamamını tek seferde kaydetti. Dinlediğinde bazı cümlelerdeki uzun duraklamaların anlamı belirsizleştirdiğini fark etti. Kayıtları yeniden düzenleyip gerekli yerlerde kısa açıklamalar ekledi; ancak konuşmanın doğal ritmini korumak için her sessizliği silmedi. Son sürümde dinleyici, hem konuyu takip edebiliyor hem de konuşmacının düşünmek için durduğu yerleri anlayabiliyordu.', 'Podcast kaydının düzenlenmesiyle ilgili parçada hangi ayrıntıdan söz edilmiştir?', '["Kayıttaki bütün sessizlikler aynı biçimde silinmiştir.","Düzenleme, açıklığı sağlarken konuşmanın doğal ritmini de korudu.","Konuşmacı, kaydı yeniden dinlemeden doğrudan yayımlamıştır.","Uzun duraklamalar, dinleyicinin konuyu izlemesini kolaylaştırmıştır.","Podcastte açıklamalar yazılı biçimde kullanılmıştır."]'::jsonb, 1, 'B seçeneği, gereksiz duraklamaların düzenlenmesiyle doğal ritmin korunmasını birlikte verir. A seçeneği metindeki ‘her sessizliği silmedi’ ayrıntısıyla çelişir.', true, 'migration', NULL, '71191be39bca63400e480017c5a7b80cd28051fdc8e2fd9b3b2562b12d08ca24'),
  ('v2-8-inference-01', 'inference', 'hard', '8', 'Okulun okuma uygulamasında bazı kitaplar hızlı tamamlanıyor, bazıları ise sık sık yarım bırakılıyordu. İlk rapor bu farkı yalnızca kitapların uzunluğuna bağladı. Öğretmenler öğrencilerle konuşunca bildirimlerin yoğun olduğu günlerde okuma sürelerinin kısaldığını ve bazı öğrencilerin ekrandaki küçük yazılarda zorlandığını gördü. Yazı boyutu ile bildirim ayarları değiştirildikten sonra yarım bırakılan kitapların sayısı azaldı; yine de bütün sınıflarda aynı oranda değişim olmadı.', 'Okuma uygulamasındaki değişimlerden hareketle aşağıdaki sonuçlardan hangisine ulaşılabilir?', '["Bir davranıştaki farkı açıklamak için ilk ölçüt yeterli sayılabilir.","Bildirimler kapatıldığında öğrencilerin okuma hızları birbirine yaklaşır.","Okuma verisi, teknik koşullar ve öğrenci farkları birlikte düşünülmelidir.","Kitap uzunluğu, okuma davranışını açıklayan tek değişken olmalıdır.","Uygulamadaki raporlar, öğrencilerin deneyimlerinden daha güvenilir bir sonuç verir."]'::jsonb, 2, 'C seçeneği, ilk açıklamanın yetersiz kalması, teknik değişiklikten sonra azalmanın görülmesi ve sınıflar arasındaki farkın sürmesi olmak üzere üç ipucunu birleştirir. B seçeneği ise sonucu gereğinden fazla geneller.', true, 'migration', NULL, '8806a9e41b3db760551de6ce4e8c60a614b68d022bed33ec8e585a39c6e8454b'),
  ('v2-8-completion-01', 'completion', 'hard', '8', 'Tarihçi, bir mahallenin geçmişini araştırırken belediye kayıtlarını mahalle sakinlerinin tuttuğu günlüklerle karşılaştırdı. Resmî kayıtlarda yeni yolun herkes için kolaylık sağladığı yazıyordu; günlüklerde ise bazı evlerin girişlerinin aylarca kapandığı anlatılıyordu. Tarihçi bu iki kaynağı birbirinin yerine koymadı, her birinin olayı farklı bir konumdan gösterdiğini belirtti. _____', 'Tarihçinin karşılaştırmasından sonra paragrafın düşünce akışına uygun cümle hangisidir?', '["Bu yüzden yolun yararlı olduğunu belirten resmî kaydı daha güvenilir kabul etti.","Günlüklerdeki kişisel ifadeleri araştırmanın dışında bıraktı.","Yolun yapımının mahallede yaşayan herkes için aynı sonucu doğurduğu sonucuna vardı.","Böylece farklı tanıklıkların sorularını ayırmak, olayı tek kaynağa indirgemeyi önledi.","İki kaynak arasındaki çelişkinin tarihî olayı anlamayı imkânsız kıldığını düşündü."]'::jsonb, 3, 'D seçeneği, resmî kayıt ile günlüklerin farklı bakışlar sunduğu önceki cümlelerden doğal olarak çıkar. A ve C seçenekleri, karşılaştırmanın kapsamını tek bir sonuca indirger.', true, 'migration', NULL, '46f65cd0f24cf4683fbf132f8d46366d07c74ca8ad4520642a6ae29624713a1a'),
  ('v2-8-flow-01', 'flow', 'hard', '8', '(I) Meydanın taş yüzeylerinde öğle sıcaklığı ölçüldü. (II) Ağaç gölgeleriyle güneş alan bölümlerin sıcaklıkları karşılaştırıldı. (III) Taşların açık veya koyu renkte seçilmesi, meydanın tarihî görünümüyle ilişkilendirildi. (IV) Yaya güzergâhlarında bekleme süreleri bu ölçümlerle karşılaştırıldı. (V) Sonuçlar, gölge ve yüzey özelliklerinin hissedilen sıcaklıkla ilişkisini gösterdi.', 'Meydanın ısı koşullarını inceleyen numaralı cümlelerden hangisi düşünce akışını bozmaktadır?', '["I","II","IV","V","III"]'::jsonb, 4, 'III. cümle taş rengini tarihî görünüşle ilişkilendirir; I, II, IV ve V ise sıcaklık ölçümü ile yaya deneyimi arasındaki inceleme zincirini sürdürür.', true, 'migration', NULL, 'babab418a5ec54088f12ec75815a98958e3c53e964fd7d3d1ee2923fcdfc9de5'),
  ('v2-hs-main_idea-01', 'main_idea', 'medium', 'high-school', 'Bir çevirmen, romandaki belirsiz bir sözcüğü her yerde aynı karşılıkla vermedi. Sözcüğün bir bölümde karakterin korkusunu, başka bir bölümde ise ironik konuşmasını desteklediğini düşündü ve çevresindeki cümleleri birlikte inceledi. Bazı okurlar tek bir karşılık beklese de çevirmen, metnin anlamını açıklığa kavuşturmak adına bu belirsizliği yok etmenin eserin sesini zayıflatacağını savundu. Okur, aynı kelimenin farklı bağlamlarda farklı tınlamalar taşıdığını izleyebildi.', 'Çeviri kararlarını açıklayan bu parçanın temel savı aşağıdakilerden hangisidir?', '["Çeviri, sözcük karşılığından çok bağlamdaki anlam katmanlarını koruma çabasıdır.","İyi bir çeviri, her sözcüğü metnin her yerinde aynı biçimde karşılamalıdır.","Okurların farklı beklentileri çevirmenin kararlarını bütünüyle belirler.","Belirsiz anlatımlar, çeviride mutlaka açık ve tek anlamlı hâle getirilmelidir.","Çevirmenin görevi, karakterlerin konuşma biçimini değiştirmeden kelimeleri aktarmaktır."]'::jsonb, 0, 'A seçeneği, aynı sözcüğün farklı bağlamlarda farklı işlevler taşımasını ve çevirmenin bu katmanları koruma kararını birlikte kapsar. B ve D seçenekleri parçadaki belirsizlik tercihinin tersini savunur.', true, 'migration', NULL, '953dc37052b4f4c589d70bec4fa43120d0473e9f60b50bc568749d7cd44f0152'),
  ('v2-hs-supporting_idea-01', 'supporting_idea', 'easy', 'high-school', 'Fotoğraf sergisinde aynı meydan, günün farklı saatlerinde çekilmiş görüntülerle yan yana gösterildi. Sabah fotoğraflarında dükkân kepenkleri ve boş kaldırımlar öne çıkarken, akşam görüntülerinde ışıkların ve bekleyen insanların meydanın kullanımını değiştirdiği görülüyordu. Küratör, fotoğrafların sırasını kronolojik kurarak ziyaretçinin yalnızca binaları değil, meydandaki hareketin gün içinde nasıl değiştiğini de izlemesini amaçladı.', 'Fotoğraf sergisinin kuruluş biçimiyle ilgili parçada hangi bilgiye yer verilmiştir?', '["Fotoğraflar akşam saatlerinde çekilmiştir.","Görüntüler kronolojik sırayla düzenlenerek meydanın gün içindeki değişimi gösterildi.","Meydanın binaları farklı yıllarda yeniden inşa edilmiştir.","Ziyaretçilerin fotoğraflara kendi sıralarını vermesi istenmiştir.","Küratör, meydandaki insan hareketinin fotoğraf sırası dışında değerlendirilmesini amaçladı."]'::jsonb, 1, 'B seçeneği, fotoğrafların kronolojik düzenlenmesi ile gün içindeki kullanım değişiminin gösterilmesi ayrıntılarını birlikte aktarır. A ve E seçenekleri metindeki açık bilgilere aykırıdır.', true, 'migration', NULL, 'e3234443c4e2949c890867fb137f83117878e1d4949a37420b537c91e024aee9'),
  ('v2-hs-inference-01', 'inference', 'hard', 'high-school', 'Bir şirket, uzaktan çalışma günlerinde üretkenliğin arttığını çalışan anketlerine dayanarak duyurdu. Ancak ankete yanıt verenlerin çoğu gönüllüydü ve yöneticiler, teslim tarihleri yaklaşan ekiplerin toplantı sayısını azalttığını ayrıca belirtti. İnsan kaynakları daha sonra yanıt vermeyen çalışanlarla görüşüp farklı ekiplerin görev türlerini karşılaştırdı. Sonuçların bazı işlerde olumlu, bazı işlerde ise değişken olması üzerine şirket tek bir çalışma modelini bütün çalışanlara uygulamak yerine ekip bazlı denemeler başlattı.', 'Şirketin uzaktan çalışma deneyiminden hareketle hangi yargıya ulaşılabilir?', '["Gönüllü ankette çoğunluk cevap verdiğinde bütün çalışanların görüşü temsil edilmiş sayılır.","Uzaktan çalışma, görevlerin niteliği değişse bile benzer sonuçlar doğurur.","Uygulamanın etkisi, katılım biçimi ve iş türü gibi koşullarla birlikte değerlendirilmelidir.","Toplantı sayısının azalması, üretkenlikteki artışın yeterli açıklamasıdır.","Yöneticilerin gözlemleri, çalışanlarla ayrıca görüşme yapılmasını gereksiz kılacak kadar yeterlidir."]'::jsonb, 2, 'C seçeneği, gönüllü katılımın sınırını, ekip görevlerindeki farkı ve toplantı sayısı gibi alternatif açıklamayı birlikte değerlendirir. B ve D seçenekleri değişken sonuçları tek nedene indirger.', true, 'migration', NULL, '95e11ed779070ec0257a5e4018e3c896c73ade3876ee96302b7aae9938751db9'),
  ('v2-hs-completion-01', 'completion', 'hard', 'high-school', 'Bir roman incelemesinde yazarın kullandığı kısa cümleler, anlatıcının olayları aceleyle aktardığı izlenimini veriyordu. Fakat aynı bölümlerde tekrarlanan bir görüntü, anlatıcının bazı anlarda geçmişe dönüp ayrıntıları yeniden düşündüğünü gösteriyordu. Eleştirmen bu iki özelliği birbirine karşıt saymak yerine, anlatıcının hız ile tereddüt arasında gidip gelmesini metnin gerilimini kuran bir yöntem olarak yorumladı. _____', 'Roman incelemesinin düşünce akışına göre sonuna hangisi getirilmelidir?', '["Böylece kısa cümlelerin metne durağan bir ritim kattığını savundu.","Bu nedenle eleştirmen, geçmişe dönüşleri incelemeden olay sırasını aktardı.","Bu görüşe göre görüntü tekrarlarının anlatımın gerilimine katkısı olmadığını savundu.","Sonuç olarak anlatım biçimi, değişen bir bakışın hareketini görünür kılıyordu.","Bunun üzerine romanı olay örgüsüne göre değerlendirmek gerektiğini savundu."]'::jsonb, 3, 'D seçeneği, kısa cümlelerdeki hız ile geriye dönüşlerdeki tereddüdün birlikte bir anlatım etkisi oluşturmasını tamamlar. Diğer seçenekler, eleştirmenin iki özelliği birlikte yorumlama yaklaşımını reddeder.', true, 'migration', NULL, '2eb77aeea29a687340bf30d783590db9c59c851c7f7cc915dd77884c2e5f779a'),
  ('v2-hs-flow-01', 'flow', 'hard', 'high-school', '(I) Roman, çocukluk anılarını yıllar sonra anlatan bir sesle başlar. (II) Anlatıcı, hatırlamadığı yerleri açıkça işaretler; böylece kesinlik iddiasını sınırlar. (III) Aynı olayın farklı bölümlerde değişen ayrıntılarla dönmesi, belleğin yeniden kurucu niteliğini düşündürür. (IV) Çocukluk anlatılarının okurda nostalji uyandırması, romanın günümüzdeki beğenisini de artırmıştır. (V) Dolayısıyla okur, anıları değişmez bir kayıt değil, bugünkü bakışın biçimlendirdiği bir yorum olarak okumalıdır.', 'Romanın anlatıcı ve bellek ilişkisini ele alan numaralı cümlelerden hangisi düşünce akışını bozmaktadır?', '["I","II","IV","V","III"]'::jsonb, 2, 'IV. cümle anlatımın güvenilirliği ve belleğin kuruluşundan okurun beğenisine geçer; I, II, III ve V ise anıların bugünkü bakışla yeniden kurulması düşüncesini geliştirir.', true, 'migration', NULL, 'fd572fcc1e7a9ecdc18c7aad153b75e7f6d53af3766e8536ed57ca468e8312d0'),
  ('v2-4-5-main_idea-02', 'main_idea', 'easy', '4-5', 'Ece, okul bahçesindeki karıncaların hep aynı taşın yanından geçtiğini gördü. Taşın önüne küçük bir dal koyunca karıncalar bir süre durdu, sonra başka bir yoldan ilerledi. Ece, yollarının rastgele değil, çevredeki işaretlere göre oluştuğunu arkadaşlarına anlattı.', 'Bu parçadan çıkarılabilecek ana düşünce aşağıdakilerden hangisidir?', '["Karıncaların izlediği yollar çevrelerindeki değişikliklerden etkilenebilir.","Karıncalar yalnızca taşların üzerinden yürür.","Ece bütün karıncaları bahçeden uzaklaştırmıştır.","Dallar karıncalar için yiyecek kaynağıdır.","Okul bahçesinde her gün yeni taşlar bulunur."]'::jsonb, 0, 'A seçeneği, karıncaların yolunun dal konunca değişmesini ve bunun çevresel etkisini birlikte verir. Diğer seçenekler parçadaki gözlemi ya daraltır ya da desteklenmeyen bir bilgi ekler.', true, 'migration', NULL, '18c884a0b46088b1712891eddaddc9e6797c55efbfba98e8d4309387a02edf09'),
  ('v2-4-5-main_idea-03', 'main_idea', 'easy', '4-5', 'Mert, ip atlama çalışırken ilk günlerde sık sık takıldı. İpi daha yavaş çevirmeyi ve ayaklarını aynı ritimde kaldırmayı deneyince atlayışları arttı. Bir hafta sonra arkadaşlarına, başarının tek seferde değil, küçük düzeltmelerle geliştiğini söyledi.', 'Mert''in deneyimi en çok hangi düşünceyi desteklemektedir?', '["Düzenli deneme ve küçük düzeltmeler beceriyi geliştirebilir.","İp atlamak için hızlı hareket etmek yeterlidir.","Spor yapmak yalnızca yarış kazanmak için gereklidir.","Arkadaşlarla çalışmak her hatayı hemen yok eder.","İlk denemede başarısız olan biri ilerleyemez."]'::jsonb, 0, 'A seçeneği, Mert''in ritmini değiştirip düzenli çalışmayla ilerlemesini özetler. Diğer seçenekler metinle uyuşmaz.', true, 'migration', NULL, '622d9b3206100025d31f23da26ab04faf12560f22aee73c7e35b5330f595600d'),
  ('v2-4-5-main_idea-04', 'main_idea', 'easy', '4-5', 'Nehir, dedesinin tarif defterinde aynı çorbanın iki farklı ölçüsünü buldu. Dedesine sorunca birinin dört kişilik, diğerinin kalabalık bir aile toplantısı için yazıldığını öğrendi. Nehir, tarifi kullanmadan önce kaç kişiye yemek hazırlayacağını belirlemeye başladı.', 'Parçanın ana düşüncesi aşağıdakilerden hangisidir?', '["Bir tarifi doğru uygulamak için miktarın hangi koşula göre verildiği bilinmelidir.","Çorbalar yalnızca aile toplantılarında yapılır.","Eski tarif defterleri kullanılmamalıdır.","Nehir artık yemek yapmayı bırakmıştır.","Dedesinin bütün tarifleri aynı ölçüdedir."]'::jsonb, 0, 'A seçeneği, ölçülerin kişi sayısına göre değiştiğini ve Nehir''in bundan çıkardığı yöntemi kapsar. Diğerleri metinde bulunmayan genellemelerdir.', true, 'migration', NULL, '327a8de0ede1c15f8733c540935a0c9a2edf7f97cf7d910a32e0a8a82fbf9690'),
  ('v2-4-5-main_idea-05', 'main_idea', 'medium', '4-5', 'Kütüphanede bozulan okuma lambaları için önce tek tek ampuller değiştirildi, ancak bazı lambalar yine yanmadı. Görevli, kabloları ve prizleri de kontrol edince sorunun birkaç farklı nedenden kaynaklandığını gördü. Bakım listesi hazırlanıp her lamba için ayrı kontrol yapılınca arızalar daha çabuk giderildi.', 'Bu parçada vurgulanan temel düşünce nedir?', '["Arızaları çözmek için tek bir nedeni varsaymak yerine sistemli kontrol yapmak gerekir.","Bütün lambaların ampulleri aynı anda değiştirilmelidir.","Kütüphanelerde yalnızca yeni lamba kullanılmalıdır.","Prizler kablolardan daha önemsizdir.","Bakım listeleri arızaları artırır."]'::jsonb, 0, 'A seçeneği, ampul değişiminin yetmediğini ve farklı parçaların planlı biçimde incelendiğini anlatır. Diğer seçenekler gözlemi yanlış yorumlar.', true, 'migration', NULL, 'c097a55c2e58cba08d34145c88ab6676dfa5e99bdba1997dc12fcc627500fb73'),
  ('v2-4-5-main_idea-06', 'main_idea', 'medium', '4-5', 'Selin, bulutların rengine bakarak yağmur yağacağını tahmin ediyordu. Öğretmeni, üç gün boyunca bulut türünü, rüzgârı ve yağış miktarını not etmelerini istedi. Notlar karşılaştırılınca yalnızca renge bakmanın yeterli olmadığı, birkaç işaretin birlikte değerlendirilmesi gerektiği ortaya çıktı.', 'Paragrafın ana düşüncesi hangi seçenekte doğru verilmiştir?', '["Yağış hakkında daha güvenilir sonuca ulaşmak için birden fazla gözlem birlikte incelenmelidir.","Hava tahmini yapmak için yalnızca öğretmenin görüşü gereklidir.","Bulutların rengi hava durumunu her zaman kesin gösterir.","Rüzgâr yağışla hiçbir zaman ilişkili değildir.","Üç günlük gözlem hava olaylarını tamamen açıklar."]'::jsonb, 0, 'A seçeneği, renk, rüzgâr ve yağış kayıtlarının birlikte değerlendirilmesi sonucunu verir. Diğer seçenekler metinle uyuşmaz.', true, 'migration', NULL, '643c5822ac12722a60487a119fe6d4668bd76f76651d8f4cd0de4433c5c7b900'),
  ('v2-4-5-main_idea-07', 'main_idea', 'medium', '4-5', 'Müzedeki görevli, ziyaretçilere salonları gösteren bir harita verdi. Haritada bazı okların tek yönlü olduğu, bazı kapıların ise yalnızca görevlilerce açıldığı belirtilmişti. Haritayı dikkatle inceleyen çocuklar, en kısa yolu aramak yerine sergilerin sırasını bozmadan ilerledi.', 'Çocukların davranışı aşağıdaki düşüncelerden hangisini gösterir?', '["Bir planı uygularken yalnızca hedefi değil, planın kurallarını da dikkate almak gerekir.","En kısa yol her zaman en doğru yoldur.","Müze haritaları yalnızca süs amacıyla hazırlanır.","Görevliler bütün kapıları ziyaretçilere açar.","Sergilerin sırası ziyaretçiler için önemsizdir."]'::jsonb, 0, 'A seçeneği, çocukların ok yönlerini ve sergi sırasını birlikte gözettiğini açıklar. Diğer seçenekler haritanın işlevini yanlış verir.', true, 'migration', NULL, 'dd07b936091da548cbf3d1c96c68eeb5871b965be3d97973fe87b06e339604c1'),
  ('v2-4-5-main_idea-08', 'main_idea', 'medium', '4-5', 'Arda, piknikte eldivenlerinden birini çimenlerin arasında bulamayınca önce oturduğu yeri aradı. Sonra yürüdüğü yolu zihninde geriye doğru canlandırıp taşın yanında durduğu anı hatırladı. Eldiveni, o noktadaki çalının altında buldu ve aramayı rastgele yapmak yerine izlediği yolu hatırlamanın işe yaradığını düşündü.', 'Bu parçadan hangi sonuç çıkarılabilir?', '["Kayıp bir eşyayı ararken hareket sırasını hatırlamak aramayı kolaylaştırabilir.","Arda eldivenini başkasının sakladığını düşünmüştür.","Çimenlik alanlarda eşya bulmak imkânsızdır.","Arda yalnızca oturduğu yerde arama yapmıştır.","Eldivenler çalıların altında bulunamaz."]'::jsonb, 0, 'A seçeneği, Arda''nın yolu geriye doğru hatırlayarak eldiveni bulmasını geneller. Diğer seçenekler metinle uyuşmaz.', true, 'migration', NULL, 'fff4d5ba824c227463ec40040554ad7720fd22d18acc0618017c1fd1f7d8ca24'),
  ('v2-4-5-main_idea-09', 'main_idea', 'medium', '4-5', 'Bahar, balkonundaki saksıda yuva yapan serçeleri izledi. Sabahları yuvaya daha çok dal taşındığını, öğleden sonra ise kuşların daha uzun süre dinlendiğini not etti. Notlarını karşılaştırınca kuşların yalnızca hava aydınlık olduğu için değil, günün farklı zamanlarındaki ihtiyaçlarına göre de davrandığını fark etti.', 'Verilen örnekler bir arada ele alındığında, parçanın ana düşüncesi aşağıdakilerden hangisidir?', '["Kuşların davranışlarını anlamak için zamanı ve davranışın amacını birlikte gözlemlemek gerekir.","Serçeler yuva yapmak için yalnızca sabahları uçar.","Balkon saksıları kuşların bütün ihtiyaçlarını karşılar.","Öğleden sonra kuşlar hiç hareket etmez.","Bahar serçelerin davranışlarını değiştirmiştir."]'::jsonb, 0, 'A seçeneği, dal taşıma ve dinlenme davranışlarının zamanla birlikte farklı ihtiyaçlara bağlandığını ifade eder. Diğer seçenekler gözlemleri eksik veya yanlış aktarır.', true, 'migration', NULL, '87de96c5f82b07347afeb9ffaaa0ce7d7995dd3f556ad13fb85695eb7f9b5963'),
  ('v2-4-5-main_idea-10', 'main_idea', 'medium', '4-5', 'Tablet kullanımını azaltmak isteyen Ozan, önce akşamları cihazı başka odaya bıraktı. Bu kez ödev sırasında bildirimleri kontrol ettiğini fark edince bildirimleri kapattı ve çalışma süresini kısa aralara böldü. Birkaç gün sonra daha uzun süre dikkatini koruyabildi; tek bir önlem yerine alışkanlığını oluşturan birkaç noktayı değiştirdiğini gördü.', 'Ozan''ın uyguladığı yöntem hangi düşünceyi destekler?', '["Bir alışkanlığı değiştirmek, onu besleyen farklı koşulları birlikte düzenlemeyi gerektirebilir.","Bildirimler yalnızca ödev bitince önemlidir.","Dikkati artırmak için cihazı tamamen yok etmek gerekir.","Uzun çalışma araları her zaman başarı getirir.","Ozan cihaz kullanımını artırmıştır."]'::jsonb, 0, 'A seçeneği, yer değiştirme, bildirimleri kapatma ve çalışma düzenini değiştirme adımlarını birlikte açıklar. Diğerleri bu adımların anlamını çarpıtır.', true, 'migration', NULL, '3c80363f5939e23fb0aa013ee811ba98bca4f0236070fa193b5fb260130634e4'),
  ('v2-4-5-main_idea-11', 'main_idea', 'hard', '4-5', 'Bisiklet kulübü, okula giden iki yolu karşılaştırdı. Kısa yolun yokuşu dikti ve sabahları servis araçlarıyla kesişiyordu; uzun yol ise daha düz, fakat yağmurdan sonra su birikintileri oluşan bir parktan geçiyordu. Öğrenciler, hava ve trafik durumuna göre hangi yolun daha güvenli olduğuna karar vermek için her iki koşulu da kaydetti.', 'Bu parçanın ana düşüncesi aşağıdakilerden hangisidir?', '["Kısa yolun dik olması, uzun yolun her koşulda daha güvenli olduğunu gösterir.","Güvenlik açısından trafik durumu, yolun uzunluğu ve yüzey koşullarından daha önemlidir.","Bisiklet rotası seçerken yolun uzunluğu, trafik, eğim ve hava koşulları birlikte karşılaştırılmalıdır.","Yağmurdan sonra oluşan su birikintileri, uzun yolu otomatik olarak elverişsiz yapar.","Servis araçlarıyla kesişmeyen yol, başka koşullara bakılmadan seçilmelidir."]'::jsonb, 2, 'C seçeneği, iki güzergâhın uzunluk, trafik, eğim ve yağmur koşulları birlikte değerlendirilerek karşılaştırılmasını kapsar. A ve D gerçek bir ayrıntıyı tek başına kesin ölçüte dönüştürür; B ise trafik koşulunu diğer verilerin önüne geçirir. E, bir koşulu yeterli saydığı için parçanın çoklu değerlendirme yaklaşımını daraltır.', true, 'migration', NULL, '537b101ff695379caef546a1bd0745563db004f5c118ffbca0b0089bebc5d154'),
  ('v2-4-5-supporting_idea-02', 'supporting_idea', 'easy', '4-5', 'Sınıf, kitaplığın üst rafına ulaşmak için küçük bir basamak kullandı. Basamağın kaymaması için altına lastik bir örtü yerleştirildi ve herkes sırayla bekledi. Böylece kitap alma işi hem kolaylaştı hem de daha güvenli oldu.', 'Parçada kitap alma işinin güvenli olması için hangi ayrıntıdan söz edilmiştir?', '["Basamağın altına lastik örtü konmasından","Rafın boyanmasından","Kitapların kaldırılmasından","Sınıfın pencerelerinin açılmasından","Herkesin aynı anda hareket etmesinden"]'::jsonb, 0, 'A seçeneği, basamağın kaymasını önleyen doğrudan ayrıntıdır. Diğer seçeneklerin hiçbiri güvenlik önlemi olarak verilmemiştir.', true, 'migration', NULL, 'c322cbd2a0a9bc3ce672d6f43effc85a9ce461353224469013352b578616e11f'),
  ('v2-4-5-supporting_idea-03', 'supporting_idea', 'easy', '4-5', 'Yaz kampında öğrenciler sabah yürüyüşünden önce mataralarını doldurdu. Rehber, suyu yürüyüşün başında bitirmemeleri için küçük yudumlarla içmelerini hatırlattı. Dönüşte herkesin hâlâ biraz suyu vardı.', 'Rehberin hangi uyarısı öğrencilerin suyunu korumasına yardımcı olmuştur?', '["Suyu küçük yudumlarla içmeleri","Yürüyüşü hızlandırmaları","Mataralarını evde bırakmaları","Yalnızca dönüşte su içmeleri","Yürüyüşü iptal etmeleri"]'::jsonb, 0, 'A seçeneği, rehberin verdiği ve sonuçla ilişkilendirilen uyarıdır. Diğerleri metinde önerilmemiştir.', true, 'migration', NULL, 'ace7c33d6f1c14e3b486517f6c4e7aac4171eda9678681444bd039c591b13afd'),
  ('v2-4-5-supporting_idea-04', 'supporting_idea', 'easy', '4-5', 'Apartman sakinleri, kullanılmayan kartonları çöpe atmak yerine bodrumdaki kutuda biriktirdi. Kutular dolunca kâğıt toplayıcısına haber verdiler. Toplanan kartonlardan elde edilen geliri bina bahçesine fidan almak için kullandılar.', 'Bahçeye fidan alınmasını sağlayan ara adım hangisidir?', '["Kartonların kâğıt toplayıcısına verilmesi","Kartonların bodrumda unutulması","Kutuların küçültülmesi","Bahçenin sulanmaması","Sakinlerin çöpleri karıştırması"]'::jsonb, 0, 'A seçeneği, kartonların gelire dönüşmesini sağlayan adımı gösterir. Diğerleri süreçte yer almaz.', true, 'migration', NULL, 'fa999c3d9409b947ce35557bfccddf1698ad689fbfe96ff1cf692d0c0cd7f420'),
  ('v2-4-5-supporting_idea-05', 'supporting_idea', 'easy', '4-5', 'Deniz fenerinin ışığı sisli gecelerde kıyıdan zor görülüyordu. Görevli, lambayı güçlendirmek yerine önce merceklerin tozunu temizledi ve ışığın yönünü denize çevirdi. Sonraki ölçümlerde aynı enerjiyle daha geniş bir alanın aydınlandığı görüldü.', 'Görevlinin ilk olarak yaptığı işlem aşağıdakilerden hangisidir?', '["Mercekleri temizleyip ışığın yönünü ayarlamak","Enerji kaynağını değiştirmek","Feneri kıyıdan uzaklaştırmak","Sisli geceleri yasaklamak","Daha büyük bir bina yapmak"]'::jsonb, 0, 'A seçeneği, görevlinin temizlik ve yön ayarından oluşan ilk müdahalesini eksiksiz verir. Diğerleri olayda yoktur.', true, 'migration', NULL, '77e21baed09a4c27b964c95d43d2b977bfdcf98d9289b4075296a11389dce105'),
  ('v2-4-5-supporting_idea-06', 'supporting_idea', 'easy', '4-5', 'Okuduğu romanda kahraman, yağmur başlayınca eve dönmek yerine pazardaki yaşlı satıcıya yardım etti. Bu küçük davranış, sonraki bölümde satıcının kahramana önemli bir bilgi vermesini açıklıyordu. Öğretmen, ayrıntıların ilerideki olayları hazırlayabileceğini söyledi.', 'Kahramanın pazardaki davranışı ileride hangi işe yaramıştır?', '["Satıcının daha sonra önemli bir bilgi vermesini açıklamıştır.","Yağmurun durmasını sağlamıştır.","Kahramanın pazarı terk etmesini sağlamıştır.","Romanın sonunu değiştirmemiştir.","Satıcının evine taşınmasına yol açmıştır."]'::jsonb, 0, 'A seçeneği, davranış ile sonraki bilgi arasındaki açık bağlantıdır. Diğer sonuçlar metinde desteklenmez.', true, 'migration', NULL, 'df161a33092fb9abd0b637b1e4eb914307b60a779549d73b049f7f8c1721abbd'),
  ('v2-4-5-supporting_idea-07', 'supporting_idea', 'easy', '4-5', 'Mahalle pazarı kurulmadan önce esnaf, kamyonların geçeceği sokağı boş bıraktı. Tezgâhlar kaldırıma sıralanınca yayalar için daralan bölümlere sarı işaretler kondu. Belediye görevlisi, pazar bitene kadar bu işaretlere uyulmasını istedi.', 'Sarı işaretlerin konma amacı nedir?', '["Yayaların daralan bölümleri güvenle geçmesini sağlamak","Tezgâhları süslemek","Kamyonların hızını artırmak","Pazarın daha uzun sürmesini sağlamak","Esnafın yerini değiştirmek"]'::jsonb, 0, 'A seçeneği, işaretlerin yayaların geçişini düzenlemek için kullanıldığını belirtir. Diğer seçenekler amaçla ilgisizdir.', true, 'migration', NULL, '50f03a0a97057e5e9a224534258984c9315d7c39c68df1283d60d0e990484269'),
  ('v2-4-5-supporting_idea-08', 'supporting_idea', 'easy', '4-5', 'Uzay sergisinde astronot kıyafetlerinin yanında eldivenlerin neden kalın olduğu anlatılıyordu. Rehber, eldivenlerin hem düşük sıcaklıktan korunmayı hem de aletleri kavramayı sağladığını gösterdi. Çocuklar, bir parçanın aynı anda birden fazla iş görebileceğini fark etti.', 'Rehberin eldivenlerle ilgili verdiği iki işlev hangisidir?', '["Sıcak tutma ve aletleri kavrama","Hızlı hareket etme ve ses çıkarma","Renk değiştirme ve ışık yayma","Su taşıma ve yemek pişirme","Kıyafeti hafifletme ve büyütme"]'::jsonb, 0, 'A seçeneği, parçadaki iki işlevi birlikte verir. Diğer ikililer sergide anlatılanlarla örtüşmez.', true, 'migration', NULL, '08a9695bdc061031333919e0e8e4b3433244275ebb67ae12daa723a1d450aaa7'),
  ('v2-4-5-supporting_idea-09', 'supporting_idea', 'medium', '4-5', 'Basketbol takımında herkes en çok sayı atan oyuncuya pas veriyordu. Rakip savunma bu düzeni fark edince hücumlar yavaşladı. Antrenör, oyuncuların farklı pozisyonlarda birbirine seçenek oluşturmasını ve pas kararını savunmanın durumuna göre vermesini istedi; sonraki antrenmanda sayı dağılımı dengelendi.', 'Antrenörün önerisi takımın hangi sorununu çözmeye yöneliktir?', '["Oyuncuların yalnızca tek bir kişiye bağlı hücum kurmasını","Pas kararlarının savunmanın durumuna göre değişmesini","Sayı dağılımının sonraki antrenmanda dengelenmesini","Farklı pozisyonlarda oyuncuların birbirine seçenek oluşturmasını","Rakip savunmanın hücum düzenini fark etmesini"]'::jsonb, 0, 'A seçeneği, rakibin fark ettiği tek oyuncuya bağımlı hücum düzeninin çözülmesi gereken sorun olduğunu belirtir. B ve D antrenörün önerdiği çözüm adımlarını, C ortaya çıkan sonucu, E ise sorunun nedenini anlatır.', true, 'migration', NULL, 'fcb58339d79b8a41f50803582848e598694cc1ae0653d27d03cb728be9b4712b'),
  ('v2-4-5-inference-02', 'inference', 'easy', '4-5', 'Lina''nın kedisi, mama kabı pencerenin yanına taşındığında daha az ürktü ve yemek yerken dışarıyı izledi. Lina, kabın yerinin kedisinin davranışını değiştirdiğini not etti.', 'Lina''nın notundan hangi çıkarım yapılabilir?', '["Mama kabının konumu kedinin rahatlığını etkileyebilir.","Kedi yalnızca geceleri yemek yer.","Pencere kedinin mamasını çoğaltır.","Lina kedisini dışarı bırakmıştır.","Kediler pencereden bakamaz."]'::jsonb, 0, 'A seçeneği, kabın yeri değişince kedinin daha rahat davranmasından çıkarılır. Diğerleri gözlemle desteklenmez.', true, 'migration', NULL, '198761a7a74bd26190c4f5c91c7eb7d7aecd211968737a2857039e384529ebe8'),
  ('v2-4-5-inference-03', 'inference', 'medium', '4-5', 'Yağmurdan sonra okul yolundaki küçük çukurda su birikiyordu. Çocuklar çukurun çevresine taş dizdi; ancak ertesi gün su yine taşların arasına doldu. Öğretmen, suyun akacağı bir kanal açılmadıkça taşların tek başına çözüm olmayacağını söyledi.', 'Öğretmenin sözünden hangi sonuç çıkarılabilir?', '["Su birikintisini önlemek için suyun akışını sağlayacak ek bir düzenleme gerekir.","Taşlar suyu tamamen yok eder.","Çukurlar yalnızca yazın oluşur.","Kanal açmak suyun yönünü değiştirmez.","Çocuklar taşları hemen kaldırmalıdır."]'::jsonb, 0, 'A seçeneği, taşların yetmemesinin nedenini ve gerekli ek düzenlemeyi açıklar. Diğer seçenekler gözleme aykırıdır.', true, 'migration', NULL, '9f4d6c57b9f59709e2bc2d88a91860c6da2d98c3ab37979d5a840e1b0fd2e75e'),
  ('v2-4-5-inference-04', 'inference', 'medium', '4-5', 'Voleybol maçında Eylül, topa sert vurmak yerine rakibin boş bıraktığı köşeye yumuşak bir vuruş yaptı. Takımı bu sayede sayı kazandı. Eylül, gücün tek başına değil, doğru yere yöneltilince işe yaradığını düşündü.', 'Eylül''ün deneyiminden hangi çıkarım yapılabilir?', '["Rakibin konumunu gözlemek, vuruş biçimi kadar önemlidir.","Sert vuruşlar her zaman sayı getirir.","Voleybolda köşelere top atılamaz.","Eylül maç boyunca hiç pas vermemiştir.","Takım yalnızca şansa güvenmiştir."]'::jsonb, 0, 'A seçeneği, boş köşeyi fark etmenin sonucu belirlediğini gösterir. Diğerleri olayın anlamını değiştirmektedir.', true, 'migration', NULL, '89953979c99c5a9d38c0c020a0dd83cd20bc2ddb1fadecb5a1912457a6cb2407'),
  ('v2-4-5-inference-05', 'inference', 'medium', '4-5', 'Hikâyedeki çocuk, kırılan saati hemen çöpe atmadı. Önce vidalarını ayırıp içindeki yayı inceledi, sonra bozuk parçayı değiştirerek saati yeniden çalıştırdı. Anlatıcı, çocuğun sabrının merakından daha belirleyici olduğunu vurguladı.', 'Bu parçadan çocuk hakkında hangi çıkarım yapılabilir?', '["Bir sorunu çözmek için sabırla deneme yapabilir.","Eşyaları onarmaktan hoşlanmaz.","Saatleri yalnızca satın alır.","Yayı nasıl kullanacağını bilmez.","Merakı olmayan bir çocuktur."]'::jsonb, 0, 'A seçeneği, saati adım adım inceleyip onarmasından çıkarılır. Metin diğer seçenekleri desteklemez.', true, 'migration', NULL, '27e1df0ecfd43ceac06a57c11c95e25a39de943918411b256222f05dd1459441'),
  ('v2-4-5-inference-06', 'inference', 'hard', '4-5', 'Göçmen kuşları izleyen ekip, ilkbaharda kuşların daha erken geldiğini kaydetti. Aynı haftalarda kıyıdaki rüzgârların zayıfladığı ve böcek sayısının arttığı da ölçüldü. Ekip, tek bir ölçümle neden belirlemek yerine bu değişkenleri birkaç yıl daha karşılaştırmaya karar verdi.', 'Ekibin kararından hangi çıkarım yapılabilir?', '["Kuşların erken gelişinde böcek artışı tek başına belirleyici olabilir.","Rüzgâr zayıfladığında kuşların daha erken gelmesi beklenir.","Ekip, erken geliş ile çevresel değişkenler arasındaki ilişkiyi doğrulamak için uzun dönemli karşılaştırmayı gerekli görmüştür.","İlkbahar gözlemleri, göç zamanının her yıl aynı biçimde değiştiğini göstermiştir.","Kuşların geliş zamanını açıklamak için yalnızca kıyı koşullarını incelemek yeterlidir."]'::jsonb, 2, 'C seçeneği, kuşların erken gelişiyle birlikte rüzgâr ve böcek verilerinin kaydedilmesini ve ekibin birkaç yıl karşılaştırma kararı almasını birleştirir. A ve B tek bir değişkenden nedensellik çıkarır; D ve E ise gözlemin kapsamını gereksiz biçimde geneller.', true, 'migration', NULL, 'c7bb834693cbec53e4b9d5aa23e8664c8267fbf1e008bb407d7334358baa70b2'),
  ('v2-4-5-inference-07', 'inference', 'medium', '4-5', 'Müze rehberi, eski köprünün yalnızca taşlarından söz etmedi; köprünün hangi mevsimde, hangi yüklerle kullanıldığını da anlattı. Ziyaretçiler, aynı yapının dayanıklılığını anlamak için malzeme kadar kullanım koşullarına bakılması gerektiğini fark etti.', 'Ziyaretçilerin fark ettiği düşünce aşağıdakilerden hangisidir?', '["Köprünün taşları, dayanıklılığı belirleyen tek ölçüttür.","Köprünün kullanım yükü arttıkça dayanıklılığı her durumda azalır.","Bir yapının dayanıklılığını anlamak için malzeme ile kullanım koşulları birlikte değerlendirilmelidir.","Ziyaretçiler eski köprüyü farklı mevsimlerde kullanmıştır.","Rehber, köprünün kullanım koşullarını malzemesinden daha önemli görmüştür."]'::jsonb, 2, 'C seçeneği, rehberin taşların yanında mevsim ve yük koşullarını da anlatmasından çıkarılır. A malzemeyi tek ölçüt sayar; B desteklenmeyen bir kesinlik kurar. D olayın ziyaretçilerle ilgili olduğunu varsayar, E ise rehberin öncelik sırası verdiğini söyler.', true, 'migration', NULL, 'f6ea1930ef227190eee2fb6a4fc17d8548fda16ec62eb30cc375217a860d0842'),
  ('v2-4-5-inference-08', 'inference', 'hard', '4-5', 'Zeynep, telefonundaki pilin hızlı tükenmesini ekran parlaklığına bağladı. Parlaklığı azaltınca değişim az oldu; konum hizmetlerini ve arka plandaki uygulamaları kapatınca pil daha uzun dayandı. Zeynep, bir sorunun görünen tek nedene indirgenmemesi gerektiğini yazdı.', 'Zeynep''in gözleminden hangi sonuç çıkarılabilir?', '["Ekran parlaklığı, pilin hızlı tükenmesinin başlangıçta düşünülen nedeni olabilir.","Farklı ayarlar birlikte incelenmeden pil sorununa ilişkin kesin bir sonuca varılamayabilir.","Konum hizmetleri ile arka plan uygulamaları, ekran parlaklığından bağımsız olarak pili etkiler.","Pil tüketimini azaltmanın güvenilir yolu pili yenisiyle değiştirmektir.","Bir ayarda değişiklik yapılması, diğer ayarları incelemeyi gereksiz kılar."]'::jsonb, 1, 'B seçeneği, parlaklık denemesinin sınırlı kalması ve başka ayarlar kapatılınca sürenin uzamasını birlikte yorumlar. A yalnızca ilk varsayımı, C ise iki ayarın etkisini belirtir; ikisi de Zeynep''in tek nedene indirgememe sonucunu tam karşılamaz. D ve E metinde desteklenmez.', true, 'migration', NULL, 'ab99c758ae41d10830241dd4fb6ea78af9d4077077e641510a5f5e117bb92178'),
  ('v2-4-5-inference-09', 'inference', 'hard', '4-5', 'Aile, hafta sonu gezisi için iki plan yaptı. Birinci plan daha kısa görünse de otobüs değişimi ve kapalı müze saatleri nedeniyle bekleme gerektiriyordu. İkinci plan biraz uzundu fakat tek otobüsle ulaşılıyor ve müze açık oluyordu; aile ikinci planı seçti.', 'Ailenin seçimi hangi çıkarımı destekler?', '["Süre bakımından kısa olan plan, diğer koşullar uygun olduğunda tercih edilebilir.","Bir gezi planı değerlendirilirken sürenin yanında aktarma ve açık olma gibi uygulanabilirlik koşulları da hesaba katılmalıdır.","Ailenin ikinci planı seçmesinin tek nedeni müzenin açık olmasıdır.","Otobüs değiştirmek, gezi planlarının uygulanmasını genellikle kolaylaştırır.","Aile, iki planı karşılaştırırken ulaşım koşullarını dikkate almamıştır."]'::jsonb, 1, 'B seçeneği, kısa planın aktarma ve müze saatleri yüzünden bekleme gerektirmesiyle ikinci planın tek araç ve açık müze avantajını birlikte değerlendirir. A yalnızca süreyi öne çıkarır; C tek bir koşulu neden sayar. D ve E olayda verilen ulaşım bilgileriyle uyuşmaz.', true, 'migration', NULL, 'd2e76b71072a99afd94280aff9e5d889587845ba006fb204ade2066f87a5a279'),
  ('v2-4-5-completion-02', 'completion', 'easy', '4-5', 'Sınıf, bitkilerin hafta boyunca susuz kalmaması için görev çizelgesi hazırladı. Her gün başka bir öğrenci toprağı kontrol edip gerekirse az miktarda su verdi. Böylece _____.', 'Paragrafı düşünce akışına uygun tamamlayan cümle hangisidir?', '["bitkilerin yerleri sürekli değişti.","sulama işi düzenli ve dengeli biçimde sürdü.","öğrenciler çizelgeyi yırtıp attı.","toprak hiç kontrol edilmedi.","bitkiler sınıftan çıkarıldı."]'::jsonb, 1, 'B seçeneği, görev çizelgesi ve günlük kontrolün doğal sonucunu verir. Diğerleri anlatılan uygulamayla çelişir.', true, 'migration', NULL, 'fec017df6c9c8ef3508f2dea1e32eb75886cef2b71fbf63fca461bfa8a38c7ed'),
  ('v2-4-5-completion-03', 'completion', 'medium', '4-5', 'Efe, kartondan bir köprü maketi yaptı. İlk denemede köprü ortasından çöktü; destekleri yalnızca uçlara koyduğunu fark etti. Ortaya da iki destek ekleyip ağırlığı yeniden dağıttı ve _____.', 'Bu cümle aşağıdakilerden hangisiyle tamamlanmalıdır?', '["maketi daha da yükseltti.","maket daha ağır yükü taşıyabildi.","köprü aynı noktadan yeniden çöktü.","desteklerin hepsini kaldırdı.","kartonu kullanmayı bıraktı."]'::jsonb, 1, 'B seçeneği, ortadaki desteklerin ağırlığı dağıtmasıyla beklenen sonucu tamamlar. Diğerleri onarımın amacına ters düşer.', true, 'migration', NULL, '24ebb19232272a004d3707192553b8beca47765c1a4271d8c8559263d7ad21fc'),
  ('v2-4-5-completion-04', 'completion', 'medium', '4-5', 'İzci grubu, haritadaki işaretleri takip ederek dereye ulaştı. Dönüşte hava kararmaya başlayınca rehber, kestirme patikaya girmek yerine sabah kullandıkları açık yolu seçti. Çünkü _____.', 'Paragrafı en uygun biçimde tamamlayan seçenek hangisidir?', '["kestirme yolun daha aydınlık olduğunu düşündü.","açık yolun yönünü ve güvenli noktalarını zaten biliyorlardı.","harita artık gerekli değildi.","dereye yeniden gitmek istediler.","hava karardıkça hızları arttı."]'::jsonb, 1, 'B seçeneği, bilinen ve güvenli yolun tercih edilme nedenini açıklar. Diğerleri rehberin kararını gerekçelendirmez.', true, 'migration', NULL, 'ed4664de70fcfdac654e957d9c86e4ebf01f303a7884783834830dd7b852ef8b'),
  ('v2-4-5-completion-05', 'completion', 'medium', '4-5', 'Parktaki yaşlı ağaçların dalları budanırken görevli önce kuru dalları işaretledi, sonra kuş yuvalarının bulunduğu bölümlere dokunmadı. Çalışma bitince _____.', 'Bu parçanın sonuna hangi cümle getirilmelidir?', '["ağaçların tamamı kesildi.","hem tehlikeli dallar alındı hem de yuvalar korundu.","kuşlar parktan uzaklaştırıldı.","budama planı iptal edildi.","kuru dallar daha da çoğaldı."]'::jsonb, 1, 'B seçeneği, kuru dalların alınması ve yuvalara dokunulmaması kararlarını birlikte sonuçlandırır. Diğerleri olayla uyuşmaz.', true, 'migration', NULL, 'a2e5e6544cfbb3157ab5d1a6814fc225fe4f6a3680fa0ab76c0bc9cb2206005d'),
  ('v2-4-5-completion-06', 'completion', 'medium', '4-5', 'Fen dersinde öğrenciler mıknatısın farklı maddelere etkisini denedi. Demir ataşlar mıknatısa yaklaşırken tahta çubuklar hareket etmedi. Öğretmen, sonuçları tabloya yazmalarını ve _____.', 'Paragrafı tamamlayan en uygun cümle hangisidir?', '["bütün maddelerin aynı davrandığını söylemelerini.","gözlemlerini maddelerin özellikleriyle ilişkilendirmelerini.","mıknatısı suya atmalarını.","ataşları görünmez hâle getirmelerini.","deneyi sonuç almadan bitirmelerini."]'::jsonb, 1, 'B seçeneği, deney sonuçlarının maddelerin özellikleriyle yorumlanmasını sürdürür. Diğer seçenekler bilimsel akışı bozar.', true, 'migration', NULL, 'e2eeda974a056226168f85ff1d5996cc070c37223e8d2f323d15166fdb127499'),
  ('v2-4-5-completion-07', 'completion', 'medium', '4-5', 'Müzik grubunda davulun sesi diğer çalgıları bastırıyordu. Öğrenciler önce davulcudan daha hafif çalmasını istedi, fakat bu kez ritim duyulmaz oldu. Sonra mikrofonların yerini ve ses düzeylerini birlikte ayarladılar; _____.', 'Bu paragraf aşağıdakilerden hangisiyle tamamlanırsa anlam bütünlüğü sağlanır?', '["davulun ritmi korunurken diğer çalgıların duyulurluğu da sağlandı.","ses dengesi için yalnızca davulun kısılmasının yeterli olacağını düşündüler.","mikrofonların yeri değişmeden de aynı dengeye ulaşabileceklerini varsaydılar.","ritim ile melodinin birbirini örtmemesi için prova düzenini yeniden kurdular.","sorunun kaynağını sadece davulcunun çalma biçiminde aramadılar."]'::jsonb, 0, 'A seçeneği, mikrofon konumu ve ses düzeylerinin birlikte ayarlanmasından beklenen dengeli sonucu verir. B önceki başarısız denemeyi tekrarlar; C yapılan ayarın etkisini yok sayar. D ve E sürecin olası yorumları olsa da paragrafın doğrudan sonucunu değil, farklı bir açıklamayı öne çıkarır.', true, 'migration', NULL, '12911ea7ee0dab3ed5c793e396cfcad433a5bc3b312ec78184fe257f584f01ef'),
  ('v2-4-5-completion-08', 'completion', 'medium', '4-5', 'Mahallede yağmur suyu biriktirmek için variller yerleştirildi. İlk sağanakta variller hızla doldu; ancak kapakları açık kaldığı için içine yapraklar ve böcekler girdi. Sakinler kapaklara ince bir süzgeç ekleyip taşma borusu takınca _____.', 'Paragrafın sonunu en iyi tamamlayan seçenek hangisidir?', '["süzgeç yaprakları tutarken taşma borusu fazla suyu kontrollü biçimde yönlendirdi.","yağmur durduğunda sakinler varilleri boşaltıp yeniden yerleştirdi.","kapaklar çıkarıldığı için böceklerin varillere girmesi kolaylaştı.","variller yağmur suyu toplamak yerine bahçede süs olarak kullanılmaya başlandı.","taşma borusu kapatılarak bütün suyun varillerde tutulması sağlandı."]'::jsonb, 0, 'A seçeneği, ince süzgecin yaprak ve böcek girişini azaltmasını, taşma borusunun da fazla suyu yönetmesini birlikte tamamlar. B metinde bulunmayan sonraki bir eylemdir; C ve E yapılan düzenlemelerin tersidir. D ise varillerin kullanım amacını değiştirir.', true, 'migration', NULL, 'f878978dc356727ee384ca8b8caa7e0cb4b6ab26c9975c851a031f9a78c47a25'),
  ('v2-4-5-completion-09', 'completion', 'medium', '4-5', 'Roman kulübü, aynı bölümdeki iki anlatıcının olayları farklı aktardığını fark etti. Biri yalnızca gördüklerini söylerken diğeri geçmişteki bilgileri de ekliyordu. Tartışmanın sonunda öğrenciler, bölümü değerlendirirken _____.', 'Verilen örnekler bir arada ele alındığında, bu cümle aşağıdakilerden hangisiyle tamamlanmalıdır?', '["olayları yalnızca gördüklerini aktaran anlatıcının gözünden değerlendirmeyi yeterli buldular.","anlatıcıların bilgi sınırlarını ve bakış açılarını karşılaştırmaları gerektiğine karar verdiler.","geçmişten gelen bilgileri, kim tarafından aktarıldığına bakmadan doğru kabul ettiler.","bakış açısı farkının olayların sırasını incelemeyi gereksiz kıldığını düşündüler.","bilgi ekleyen anlatıcıyı güvenilir, yalnızca gördüklerini söyleyeni önemsiz saydılar."]'::jsonb, 1, 'B seçeneği, iki anlatıcının farklı bilgi kapsamlarını ve olaylara bakışlarını karşılaştırma gereğini tamamlar. A ve E anlatıcılardan birini tek başına yeterli sayar; C ve D ise anlatım farkının değerlendirilmesini daraltır.', true, 'migration', NULL, '0ae7bbe5f1aa71bd7e87f0bb2b6e2b7ebabd506081f555d78ce8bdb246f5c81a'),
  ('v2-4-5-flow-02', 'flow', 'easy', '4-5', '(I) Okul bahçesindeki çiçeklerin renkleri kaydedildi. (II) Her renkteki çiçek sayısı sayıldı. (III) Sonuçlar sınıf panosuna tablo olarak asıldı. (IV) Kompost kutusunun yanındaki saksıların renkleri seçildi. (V) Öğrenciler en çok hangi rengin bulunduğunu tabloya bakarak söyledi.', 'Çiçek gözlemlerini anlatan düşünce akışını bozan cümle hangisidir?', '["I","II","III","V","IV"]'::jsonb, 4, 'IV. cümle saksı renklerine geçer; diğer cümleler çiçekleri sayma ve sonuçları değerlendirme zincirini sürdürür.', true, 'migration', NULL, '9d6d6b64b8a272828b0c90e5ee884887014ef22b733bd65127d1c56e70954221'),
  ('v2-4-5-flow-03', 'flow', 'medium', '4-5', '(I) Bahçedeki kompost kutusuna sebze kabukları eklendi. (II) Kutunun nemi her iki günde bir kontrol edildi. (III) Kuru kaldığında biraz su ve kuru yaprak ilave edildi. (IV) Bisiklet yolundaki dinlenme banklarının boyası yenilendi. (V) Ölçümler, kompostun toprağın verimine katkısını değerlendirmek için karşılaştırıldı.', 'Kompost çalışmasının akışını bozan cümle hangisidir?', '["I","II","III","IV","V"]'::jsonb, 3, 'IV. cümle dinlenme banklarının boyasına geçer; I, II, III ve V kompostun hazırlanıp etkisinin değerlendirilmesiyle ilişkilidir.', true, 'migration', NULL, '233cba4164b1213fe42801a6a8d97c1c824e0a4bd0098bdab121529f3262389e'),
  ('v2-4-5-flow-04', 'flow', 'medium', '4-5', '(I) Bisiklet yolundaki uyarı levhaları fotoğraflandı. (II) Levhaların sürücüler tarafından görülme uzaklığı ölçüldü. (III) Görülmeyen levhaların çevresindeki dallar budandı. (IV) Arı kovanlarının yanındaki bal kavanozları etiketlendi. (V) Budamadan sonra aynı uzaklık ölçümleri tekrarlandı.', 'Bisiklet yolu incelemesinde akışı bozan cümle hangisidir?', '["I","II","III","IV","V"]'::jsonb, 3, 'IV. cümle bal kavanozlarının etiketlerine geçer; diğerleri levhaların görünürlüğünü ölçme ve iyileştirme sürecini anlatır.', true, 'migration', NULL, 'cdb40fdbae7ba8515f5809ff8b03d348d265d128aba2e827007cf7f24a5727f4'),
  ('v2-4-5-flow-05', 'flow', 'medium', '4-5', '(I) Arıcılar kovandaki peteklerin doluluk oranını inceledi. (II) Havanın serinlediği günlerde arıların uçuş süresi kısaldı. (III) Kovan girişine rüzgârı azaltan bir örtü yerleştirildi. (IV) Parktaki salıncakların yanında çimlerin biçim yüksekliği ölçüldü. (V) Sonraki gözlemlerde uçuş süresi ile kovan sıcaklığı karşılaştırıldı.', 'Arıların çalışma koşullarını anlatan akışı bozan cümle hangisidir?', '["I","II","III","IV","V"]'::jsonb, 3, 'IV. cümle çimlerin biçim yüksekliğine geçer; I, II, III ve V kovan koşulları ile arıların uçuşunu izleyen zinciri oluşturur.', true, 'migration', NULL, '7cd6b8323c9c1e8bb887b5cd54ca4bfca33c687c630c70f5e19a686d4e34c10f'),
  ('v2-4-5-flow-06', 'flow', 'medium', '4-5', '(I) Park görevlisi salıncak zincirlerinin bağlantılarını ve oturma yüzeylerini kontrol etti. (II) Gevşek bağlantılar sıkıştırıldı, yüzeylerdeki kirler temizlendi. (III) Bakım öncesi ve sonrası salıncakların hareket mesafeleri ölçülerek karşılaştırıldı. (IV) Salıncak alanındaki zemin kaplaması için farklı renk örnekleri yerleştirildi. (V) Güvenlik ölçümleri uygun çıkınca salıncaklar kullanıma açıldı.', 'Salıncak bakımının aşamalarını anlatan numaralı cümlelerden hangisi düşünce akışını bozmaktadır?', '["I","II","III","V","IV"]'::jsonb, 4, 'IV. cümle zemin kaplamasının renk seçimine geçer; I, II, III ve V ise zincir ve yüzey kontrolü, onarım, ölçüm ve güvenlik sonucundan oluşan bakım zincirini sürdürür.', true, 'migration', NULL, '32f984549a5dacedae6b3651d9a715ccea666f49b428902d2b98cf2bc79a9b55'),
  ('v2-4-5-flow-07', 'flow', 'medium', '4-5', '(I) Hava istasyonundaki basınç sensörü sabah ölçümünden önce kalibre edildi. (II) Öğle saatinde rüzgâr yönü, hızı ve basınç değeri aynı kayıt formuna işlendi. (III) Akşam ölçümleri, gün içindeki değişimi görmek için sabah ve öğle verileriyle karşılaştırıldı. (IV) İstasyonda gözlenen bulutların fotoğrafları mevsim arşivine eklendi. (V) Birbirini destekleyen ölçümler, ertesi günün kısa vadeli tahmininde kullanıldı.', 'Hava istasyonundaki kısa vadeli tahmin çalışmasının akışını bozan cümle hangisidir?', '["I","II","III","V","IV"]'::jsonb, 4, 'IV. cümle aynı istasyonda yapılan bir gözlemi anlatsa da fotoğrafları mevsim arşivine ekleme işi, sensör verilerini karşılaştırıp kısa vadeli tahmine bağlayan zincire katılmaz. I, II, III ve V kalibrasyon, ölçüm, karşılaştırma ve kullanım sırasını sürdürür.', true, 'migration', NULL, 'ad4ac2fe567e2db09a588bcb5e3f34c8ce9195320d59c3aa6885b887abdb916e'),
  ('v2-4-5-flow-08', 'flow', 'medium', '4-5', '(I) Müze ekibi, seramik parçalarının yüzeylerini farklı açılardan aydınlatarak inceledi. (II) Parçaların kenarları birleştirilip olası kap biçimleri çizildi. (III) Çizimler, aynı döneme ait katalog örnekleriyle biçim ve süsleme bakımından karşılaştırıldı. (IV) Parçaların sergilendiği vitrinin ışık düzeyi gün boyunca ölçüldü. (V) Karşılaştırma sonunda parçaların hangi kaba ait olabileceği konusunda iki öneri oluşturuldu.', 'Seramik parçalarının yeniden birleştirilmesine yönelik incelemede düşünce akışını bozan cümle hangisidir?', '["I","II","III","V","IV"]'::jsonb, 4, 'IV. cümle vitrinin sergileme koşuluna geçer; I, II, III ve V ise yüzey incelemesinden biçim çizimine, katalog karşılaştırmasına ve kap önerilerine ilerleyen çözümleme zincirini sürdürür.', true, 'migration', NULL, 'e69996fab38b5b8512d85cffcae907d2b5b8c26970e21aa293aff7c279393028'),
  ('v2-8-main_idea-02', 'main_idea', 'easy', '8', 'İlçe belediyesi, eski otobüs duraklarının yanına yağmur suyu depoları yerleştirdi. Depolanan su, yazın çevredeki fidanları sulamak için kullanıldı. Proje, küçük bir düzenlemenin hem su tüketimini hem de bakım giderlerini azaltabileceğini gösterdi.', 'Bu metnin verdiği bilgiler ışığında, bu parçanın ana düşüncesi aşağıdakilerden hangisidir?', '["Otobüs durakları yalnızca yolcuları yağmurdan korur.","Yağmur suyu depolamak fidan bakımında kaynak tasarrufu sağlayabilir.","Fidanlar yazın sulanmamalıdır.","Belediyeler durakları kaldırmalıdır.","Depolardaki su yalnızca içme amacıyla kullanılır."]'::jsonb, 1, 'B seçeneği, depolanan yağmur suyunun fidan sulama ve tasarruf sonuçlarını birlikte özetler. Diğerleri metinde desteklenmez.', true, 'migration', NULL, 'cf813f77006d916d215015d723ea73d72c3fe49cf47dc24de98d6d1bd3b6c23d'),
  ('v2-8-main_idea-03', 'main_idea', 'medium', '8', 'Bir okul, öğrencilerin teneffüste telefon kullanmasını tamamen yasaklamak yerine ortak bir dolap oluşturdu. Öğrenciler ders boyunca telefonlarını bu dolaba bıraktı; teneffüste kısa süreliğine alabildi. Bir ay sonunda derse geç kalma ve bildirim nedeniyle bölünme şikâyetleri azaldı.', 'Parçada savunulan temel düşünce nedir?', '["Telefonlar öğrencilerin çantasında tutulmalıdır.","Aşırı kısıtlama yerine belirli kurallar koymak, teknoloji kullanımını daha düzenli hâle getirebilir.","Her teknoloji kullanımı sınırsız bırakılmalıdır.","Teneffüslerde ders işlenmelidir.","Dolaplar yalnızca öğretmenler içindir."]'::jsonb, 1, 'B seçeneği, tamamen yasaklamak yerine zaman ve yer sınırı getirilmesinin sonuçlarını açıklar. Diğerleri uygulamanın amacını karşılamaz.', true, 'migration', NULL, 'b2c3789c814bfdeb1431703de7f95d80627ad56e033971b3982e7a0e0ebfd0ba'),
  ('v2-8-main_idea-04', 'main_idea', 'medium', '8', 'Kıyı araştırma ekibi, deniz çayırlarının bulunduğu alanlarda tekne demirlerinin iz bıraktığını belirledi. Bunun üzerine bazı koylarda sabit bağlama şamandıraları kuruldu ve teknelere demir atmama uyarısı yapıldı. Bir sonraki sezonda izlerin azaldığı görüldü; ancak ekibin düzenli denetimi sürdürmesi gerektiği vurgulandı.', 'Bu parçanın ana düşüncesi hangi seçenekte verilmiştir?', '["Deniz çayırları teknelerin hareketini tamamen engeller.","Kıyı ekosistemini korumak için önlem almak kadar uygulamayı izlemek de önemlidir.","Tekneler yalnızca açık denizde demir atabilir.","Şamandıralar bütün deniz kirliliğini ortadan kaldırır.","Denetim yapılmadan da izler kendiliğinden yok olur."]'::jsonb, 1, 'B seçeneği, şamandıra ve uyarının etkisinin denetim gereksinimiyle birlikte ele alınmasını özetler. Diğer seçenekler aşırı veya yanlış genellemelerdir.', true, 'migration', NULL, 'd19903fe8c6c0b44fa00c874410fd672c0f0ebab9e8e8dc2f36c782a041c0916'),
  ('v2-8-main_idea-05', 'main_idea', 'medium', '8', 'Bir yayınevi, kitap kapağını seçerken yalnızca tasarım ekibinin oyuna başvurmadı. Farklı yaşlardan okurlara iki taslak gösterildi, hangi ayrıntıların dikkat çektiği soruldu ve geri bildirimler tasarımcıların görüşleriyle karşılaştırıldı. Son kapak, bu verilerden ortaklaşan noktalar çıkarılarak hazırlandı.', 'Yayınevinin yaklaşımı hangi ilkeyi vurgulamaktadır?', '["Kapak tasarımında okur görüşü gereksizdir.","Farklı kaynaklardan gelen geri bildirimleri karşılaştırmak daha isabetli bir karar sağlayabilir.","Tek bir uzmanın kararı bütün verilerden üstündür.","Taslaklar okurlara gösterilmemelidir.","Tasarım yalnızca yaşça büyük okurlara sorulmalıdır."]'::jsonb, 1, 'B seçeneği, okur geri bildirimleri ile tasarımcı görüşlerinin karşılaştırılmasını doğru biçimde verir. Diğerleri yöntemin tersini savunur.', true, 'migration', NULL, 'd713c8fd8181971669ac18e0dfd643b08f08f3e38600c0901ffc3dcb1308b0a5'),
  ('v2-8-main_idea-06', 'main_idea', 'medium', '8', 'Kent arşivinde aynı olayla ilgili iki gazete haberi bulundu. Biri olayın hemen sonrasındaki gözlemleri, diğeri ise yıllar sonra yapılan bir röportajı içeriyordu. Araştırmacı, haberleri tek başına doğru kabul etmek yerine tarihlerini ve anlatıcıların konumlarını dikkate alarak birlikte okudu.', 'Parçadaki uygulama ve sonuçlar düşünüldüğünde, parçanın ana düşüncesi aşağıdakilerden hangisidir?', '["Eski haberler her zaman yanlıştır.","Bir olayı anlamak için kaynakların zamanı ve bakış açısı da değerlendirilmelidir.","Röportajlar gazete haberlerinden daha değersizdir.","Araştırmacı yalnızca ilk haberi kullanmıştır.","Kaynakların tarihini bilmek gereksizdir."]'::jsonb, 1, 'B seçeneği, iki kaynağın tarih ve anlatıcı konumlarıyla birlikte değerlendirilmesi gereğini özetler. Diğerleri metindeki yöntemi daraltır.', true, 'migration', NULL, 'da2a5347472f8f5366f07b10bf66b5cd054733c4eacf2d51a87fe8f3fce36a25'),
  ('v2-8-main_idea-07', 'main_idea', 'medium', '8', 'Mahalle kooperatifi, ortak sebze bahçesinde ürün veriminin düştüğünü fark etti. Toprağı değiştirmek yerine sulama saatlerini, gölge oranını ve kullanılan kompost miktarını ayrı ayrı kaydettiler. Üç ay sonra verimin en çok öğle sıcağında yapılan sulamadan etkilendiğini belirleyip programı değiştirdiler.', 'Bu parçadan çıkarılabilecek ana düşünce nedir?', '["Verim düşüklüğünün tek nedeni topraktır.","Sorunu doğru tanımak için olası etkenleri ayrı ayrı gözlemlemek gerekir.","Bahçede kayıt tutmak zaman kaybıdır.","Kompost bütün sorunları çözer.","Sulama saati ürünleri etkilemez."]'::jsonb, 1, 'B seçeneği, kooperatifin etkenleri ayrı ayrı kaydedip sorunu belirlemesini açıklar. Diğer seçenekler gözlemin sonucuyla çelişir.', true, 'migration', NULL, '602e93d84cd83c6dc6b79361dba0ee50cea1ca1c4fa30866c5b58ce9865b35cd'),
  ('v2-8-main_idea-08', 'main_idea', 'hard', '8', 'Bir üniversite kulübü, kampüsteki sessiz çalışma alanlarını artırmak istedi. Öğrencilerin yalnızca gürültü şikâyetlerini toplamakla yetinmeyip günün saatlerine göre doluluk, yankı ve geçiş yoğunluğu ölçtüler. Sonuçlar, bazı odaların küçük müdahalelerle sessizleşebileceğini, bazılarında ise kullanım planının değişmesi gerektiğini gösterdi.', 'Bu anlatının bağlamı göz önüne alındığında, parçanın ana düşüncesi aşağıdakilerden hangisidir?', '["Gürültü şikâyetleri, çalışma alanlarını yeniden düzenlemek için yeterli göstergedir.","Sessiz çalışma alanlarını iyileştirmek, kullanıcı deneyimini farklı ölçümlerle birlikte değerlendirmeyi gerektirir.","Yankı sorunu bulunan odalarda kullanım planını değiştirmek, fiziksel müdahaleden daha etkilidir.","Doluluk verileri, sessiz alan ihtiyacını gürültü ölçümlerinden daha iyi gösterir.","Her oda küçük bir akustik müdahaleyle sessizleştirilebilir."]'::jsonb, 1, 'B seçeneği, şikâyetlerin doluluk, yankı ve geçiş ölçümleriyle birlikte değerlendirilmesini ve odalara göre farklı çözümler geliştirilmesini kapsar. A tek veri kaynağını yeterli sayar; C ve D çözümü tek bir etkene indirger. E ise bütün odalar için aynı sonucu varsayar.', true, 'migration', NULL, 'ff68a111ca86ad9c6b52308b35d68a988ad87bbab3774c584f07393b739bd739'),
  ('v2-8-supporting_idea-02', 'supporting_idea', 'easy', '8', 'Sınıf gazetesi hazırlanırken haberler önce başlıklarına göre ayrıldı. Spor haberleri mavi, kültür haberleri yeşil bir dosyaya kondu. Editör, bu düzenin aranan haberi daha hızlı buldurduğunu söyledi.', 'Haberlerin dosyalara ayrılmasının doğrudan yararı nedir?', '["Gazetenin sayfa sayısını artırmak","Aranan habere daha hızlı ulaşmak","Başlıkları kaldırmak","Haberleri kısaltmak","Dosyaları renksiz yapmak"]'::jsonb, 1, 'B seçeneği, renkli dosyalama düzeninin metinde belirtilen doğrudan yararıdır. Diğerleri bu düzenle ilişkilendirilmemiştir.', true, 'migration', NULL, '48f1407beb4efcbf3aff44f3916e051c2d8f5216497451f32d6869586623f4b4'),
  ('v2-8-supporting_idea-03', 'supporting_idea', 'easy', '8', 'Tren yolculuğunda Elif, pencereden gördüğü istasyon adlarını küçük bir deftere yazdı. Eve dönünce adları haritadaki noktalarla eşleştirdi. Böylece yolculuk boyunca geçtiği yerlerin sırasını daha kolay hatırladı.', 'Elif''in deftere not almasının amacı nedir?', '["İstasyonları değiştirmek","Gördüğü yerleri sıralı biçimde hatırlamak","Tren biletini saklamak","Haritayı gizlemek","Yolculuğu kısaltmak"]'::jsonb, 1, 'B seçeneği, notların istasyon sırasını hatırlamaya hizmet ettiğini belirtir. Diğer amaçlar metinde yoktur.', true, 'migration', NULL, '025881915ea3f77d5227a9ac877da44e5eed6ce724ebc0beb7623254a52ef8cd'),
  ('v2-8-supporting_idea-04', 'supporting_idea', 'easy', '8', 'Fotoğraf kulübü, aynı meydanı sabah ve akşam çekti. Sabah fotoğrafında uzun gölgeler, akşam fotoğrafında ise vitrin ışıkları belirgindi. Öğrenciler, ışığın yalnızca görüntüyü aydınlatmadığını, fotoğrafın dikkat merkezini de değiştirdiğini tartıştı.', 'İki fotoğraf arasındaki farkı açıklayan ayrıntı hangisidir?', '["Meydanın başka bir şehre taşınması","Günün farklı saatlerinde ışığın ve gölgelerin değişmesi","Kameraların tamamen bozulması","Öğrencilerin fotoğraf çekmemesi","Vitrinlerin sabah kapalı olması"]'::jsonb, 1, 'B seçeneği, sabah-akşam ışık ve gölge farkını doğrudan açıklar. Diğerleri verilen görsel ayrıntılarla uyuşmaz.', true, 'migration', NULL, 'ca810fd6fc556219d5662f1658844f6a2125069ab441e5ad4cb24c9c0e66c2ca'),
  ('v2-8-supporting_idea-05', 'supporting_idea', 'easy', '8', 'Tarih öğretmeni, öğrencilerden bir yapının geçmişini araştırırken yalnızca internet sayfalarına bağlı kalmamalarını istedi. Mahallede yaşayan yaşlılarla görüşmeleri, eski fotoğrafları incelemeleri ve buldukları bilgileri tarihleriyle kaydetmeleri gerektiğini söyledi.', 'Öğretmenin önerdiği araştırma adımlarından biri hangisidir?', '["Bütün bilgileri tarihsiz yazmak","Eski fotoğrafları ve sözlü anlatımları da incelemek","Yalnızca tek bir internet sayfasını kopyalamak","Görüşme yapmaktan kaçınmak","Yapının geçmişini tahmin etmek"]'::jsonb, 1, 'B seçeneği, öğretmenin açıkça önerdiği iki kaynağı verir. Diğerleri yönergenin tersidir.', true, 'migration', NULL, 'd02d824810f9151d08c55c7de74bfe99b0039a66f58b837c91a09b48c7c484d7'),
  ('v2-8-supporting_idea-06', 'supporting_idea', 'easy', '8', 'Tiyatro ekibi, sahne dekorunun oyuncuların hareketini daralttığını fark etti. Dekoru tamamen kaldırmak yerine ağır parçaları kenara taşıdı ve geçiş yollarını işaretledi. Prova sırasında oyuncuların duraksamaları azaldı.', 'Dekorda yapılan değişikliğin desteklediği ayrıntı nedir?', '["Sahnenin ışıkları kapatılmıştır.","Geçiş yolları açılarak oyuncuların daha rahat hareket etmesi sağlanmıştır.","Oyuncuların sayısı azaltılmıştır.","Dekorun bütün parçaları atılmıştır.","Provalar iptal edilmiştir."]'::jsonb, 1, 'B seçeneği, parçaların kenara taşınması ve yolların işaretlenmesiyle oluşan sonucu anlatır. Diğer seçenekler gerçekleşmemiştir.', true, 'migration', NULL, 'f9de822c9c9c7c0bb27b05470f08cbb4211c17962e311f12ec7e69c9a20eb459'),
  ('v2-8-supporting_idea-07', 'supporting_idea', 'easy', '8', 'Bir araştırma ekibi, okul servislerinin gecikmesini incelerken yalnızca şoförlerin görüşünü almadı. Öğrencilerin bekleme sürelerini, duraklardaki araç yoğunluğunu ve hava koşullarını da kaydetti. Rapor, gecikmelerin tek bir nedene bağlanamayacağını gösterdi.', 'Raporun tek bir nedene varılamayacağını göstermesinde hangi veri etkili olmuştur?', '["Sadece şoförlerin tahminleri","Servis güzergâhlarının silinmesi","Bekleme, yoğunluk ve hava koşullarına ilişkin kayıtlar","Öğrencilerin görüşlerinin yok sayılması","Hava koşullarının hiç ölçülmemesi"]'::jsonb, 2, 'C seçeneği, raporda sayılan üç veri grubunu birlikte verir. Diğerleri araştırmanın kapsamını yanlış aktarır.', true, 'migration', NULL, '79a0098183f751a8949fc38f630bec55ad419c76753ba07921f1d889c08bc7e5'),
  ('v2-8-supporting_idea-08', 'supporting_idea', 'medium', '8', 'Bir dergi, iklim haberlerini yayımlamadan önce haber metnindeki sıcaklık verilerini ham ölçüm tablolarıyla karşılaştırdı. Bir haberde ortalama yerine en yüksek değer kullanıldığı için başlık değiştirildi ve iki değer arasındaki fark açıklandı. Editör, okurun sonucu doğru yorumlayabilmesi için verinin nasıl seçildiğinin belirtilmesi gerektiğini savundu.', 'Başlığın değiştirilmesine yol açan ayrıntı hangisidir?', '["Haber metnindeki verilerin ham ölçüm tablolarıyla karşılaştırılması","Ortalama sıcaklık yerine en yüksek sıcaklık değerinin başlıkta kullanılması","İki değer arasındaki farkın başlıkta açıklanması","Verinin nasıl seçildiğinin belirtilmesi gerektiği yönündeki editör görüşü","Sıcaklık verilerinin yayımlanmadan önce yeniden okunması"]'::jsonb, 1, 'B seçeneği, bir haberde ortalama yerine en yüksek değerin kullanılmasının başlığın değiştirilmesine yol açtığını belirtir. A ve E denetim sürecinin parçalarıdır; C ve D ise değişikliğin ardından açıklanan ya da savunulan noktaları verir.', true, 'migration', NULL, '815e77106e1256d7d2cbbb5d5c24bf1d44158c138fc20a728acaddf31c5a4911'),
  ('v2-8-inference-02', 'inference', 'easy', '8', 'Sınıfta yapılan ankette öğrencilerin çoğu teneffüste kütüphaneye gitmek istediğini söyledi. Kütüphaneci, yoğunluğu azaltmak için sınıflara farklı günler önerdi ve ilk hafta girişte sıra oluşmadı.', 'Bu uygulamanın amacı hakkında hangi çıkarım yapılabilir?', '["Kütüphaneyi tamamen kapatmak","Öğrencilerin kitap okumasını engellemek","İlgiyi günlere dağıtarak yoğunluğu yönetmek","Anketi geçersiz saymak","Giriş sırasını uzatmak"]'::jsonb, 2, 'C seçeneği, farklı gün önerisinin yoğunluğu dağıtma amacını çıkarır. Diğerleri sonuçla ters düşer.', true, 'migration', NULL, 'c711d0393319736cf5ed573e696ba8025b52a9b7ab1969b6633fd56e6f62b949'),
  ('v2-8-inference-03', 'inference', 'medium', '8', 'Yaşlı çınarın çevresine konan banklar yağmurdan sonra uzun süre ıslak kalıyordu. Görevli, bankları kaldırmak yerine ağaç dallarının suyu hangi yöne akıttığını gözlemledi ve bankların yerini birkaç metre değiştirdi. Yeni konumlarda kuruma süresi kısaldı.', 'Görevlinin kararından hangi sonuç çıkarılabilir?', '["Bankların malzemesi değiştirilmiştir.","Çınar artık sulanmamaktadır.","Sorunun nedeni su akışıyla ilişkili olabileceği için konum düzenlenmiştir.","Yağmur bankları etkilemez.","Banklar gövdeye tamamen yaslanmıştır."]'::jsonb, 2, 'C seçeneği, dallardan gelen su akışının konumla ilişkisini ve buna göre yapılan düzenlemeyi açıklar. Diğerleri metin tarafından desteklenmez.', true, 'migration', NULL, 'c6ae548c9a76fa7baa7f487ea3e87a07f1363a2dd40fcd9e079bf295b95f6f9c'),
  ('v2-8-inference-04', 'inference', 'medium', '8', 'Robotik takımının aracı düz zeminde iyi ilerliyor, fakat halının kenarında tekerlekleri takılıyordu. Öğrenciler motoru güçlendirmek yerine tekerleklerin açısını ve gövdenin yüksekliğini değiştirdi. Araç, aynı motorla farklı yüzeyleri geçebildi.', 'Takımın çözümünden hangi çıkarım yapılabilir?', '["Motor gücü her yüzey sorununu çözer.","Halının kenarı düz zeminden daha kolaydır.","Hareket sorunları bazen aracın tasarım ayrıntıları değiştirilerek giderilebilir.","Tekerlek açısı hareketi etkilemez.","Takım aracı kullanmayı bırakmıştır."]'::jsonb, 2, 'C seçeneği, motoru değil tasarım ayrıntılarını değiştirmenin işe yaradığını çıkarır. Diğerleri gözleme aykırıdır.', true, 'migration', NULL, '864aeac8989628c613ae8a1a43fece5ea4bcaa273e29b006b32ad4385c3b5b72'),
  ('v2-8-inference-05', 'inference', 'hard', '8', 'Bir kasabanın su tüketimi yaz aylarında arttı. Yetkililer önce bütün sayaçları değiştirmeyi planladı; ancak saatlik veriler, artışın çoğunun bahçe sulama saatlerinde gerçekleştiğini gösterdi. Kampanya, sayaç yenilemek yerine akşam saatlerinde sulamayı ve kaçak kontrolünü teşvik edecek biçimde düzenlendi.', 'Yetkililerin plan değiştirmesinden hangi çıkarım yapılabilir?', '["Sayaçları yenilemek, tüketim artışının nedenini bilmeden uygulanabilecek genel bir önlemdir.","Bahçe sulama saatleri, yaz aylarındaki artışın görüldüğü önemli zaman aralığıdır.","Veriler, geniş bir müdahale yerine tüketim artışının görüldüğü davranışlara odaklanmayı sağlamıştır.","Kampanyanın etkili olması için bütün sayaçların aynı anda değiştirilmesi gerekir.","Saatlik kayıtlar, tüketim davranışları hakkında karar vermeye elverişli değildir."]'::jsonb, 2, 'C seçeneği, saatlik verilerin artışı bahçe sulama saatleriyle ilişkilendirmesi ve kampanyanın buna göre düzenlenmesinden çıkarılır. A ve B tek başına verinin yönlendirdiği plan değişikliğini açıklamaz; D ve E metindeki kararı tersine çevirir.', true, 'migration', NULL, '495b133417602177528060a732632f338ad86bcdcbb55cc1ce08f50549ce0ee4'),
  ('v2-8-inference-06', 'inference', 'hard', '8', 'Arkeologlar, kazıda bulunan iki seramik parçanın aynı kaba ait olup olmadığını anlamak için yalnızca renklerine bakmadı. Kırık yüzeylerin eğimini, hamurun içindeki mineralleri ve parçaların bulunduğu katmanın tarihini karşılaştırdılar. Bulgular, renkleri benzer olsa da parçaların farklı kaplara ait olduğunu gösterdi.', 'Bu çalışmadan hangi çıkarım yapılabilir?', '["Renk benzerliği, parçaların aynı kaba ait olma ihtimalini artırdığı için ilk inceleme için yeterlidir.","Kırık yüzey eğimi ve mineral yapısı, parçaların aynı kaba ait olabileceğine dair güçlü kanıt sunar.","Bir parçanın kökenini belirlemek için görünüşe ek olarak yapısal ve tarihsel kanıtlar birlikte değerlendirilmelidir.","Aynı katmandan çıkan seramikler genellikle aynı kaba ait sayılabilir.","Parçaların farklı kaplara ait olduğu yalnızca renk farkından anlaşılmıştır."]'::jsonb, 2, 'C seçeneği, renk karşılaştırmasına ek olarak kırık yüzey, mineral ve katman tarihinin incelenmesinden çıkarılır. A görünüşü başlangıç ipucu olarak makul kılsa da tek başına yeterli değildir; B ise incelemelerin aynı kaba işaret ettiğini varsayar, oysa sonuç farklı kapları gösterir.', true, 'migration', NULL, 'd026b3129518b15a2577e5c917a4b96e205a120c3c4daf8e9cba616d60ebd93c'),
  ('v2-8-inference-07', 'inference', 'medium', '8', 'Bir haber videosunda kalabalık bir meydanın görüntüsü kullanıldı, fakat görüntünün hangi gün çekildiği belirtilmedi. Araştırmacı aynı meydanın farklı tarihlerdeki kayıtlarını bulunca videodaki kalabalığın özel bir etkinlik gününe ait olabileceğini fark etti. Tarih bilgisi eklenmeden görüntünün genel durumu temsil ettiği söylenemedi.', 'Araştırmacının fark ettiği sorun nedir?', '["Görüntü, özel bir etkinlik gününü yansıtıyor olabilir; bu ihtimal belirtilmelidir.","Etkinlik günündeki kalabalık, meydanın olağan kullanımına ilişkin bir ipucu sağlayabilir.","Tarih belirtilmediği için görüntünün olağan durumu temsil ettiği sonucuna tek başına varılamaz.","Aynı meydanın farklı tarihlerdeki kayıtları, tarih bilgisi olmasa da aynı anlamı taşır.","Görüntünün çözünürlüğü, temsil sorununu tek başına ortadan kaldırır."]'::jsonb, 2, 'C seçeneği, tarihin bilinmemesinin özel etkinlik kalabalığını olağan durum gibi yorumlama riskini doğurduğunu açıklar. A ve B araştırmacının fark ettiği olası bağlamları belirtir, ancak tarih eksikliğinin temsil sorununu çözmez. D ve E bu sorunu göz ardı eder.', true, 'migration', NULL, '27658c34fd3f39a407753c0ae75e372f3cdb9cef277b2d5099700a8985e368e5'),
  ('v2-8-inference-08', 'inference', 'hard', '8', 'Bir öğrenci, iki çalışma yöntemini denedi: İlk hafta her gün uzun bir oturum yaptı, ikinci hafta ise konuları kısa aralıklarla tekrarladı. Sınav öncesi yaptığı hatalar ikinci yöntemde daha azdı; öğrenci, yalnızca çalışma süresinin değil, tekrarların zamana yayılmasının da etkili olabileceğini düşündü.', 'Öğrencinin düşüncesinden hangi çıkarım yapılabilir?', '["Uzun çalışma oturumları, bu öğrencinin denemesinde daha başarılı yöntemi göstermiştir.","İkinci yöntemdeki daha az hata, tekrarların zamana yayılmasının olası etkisini düşündürmüştür.","Öğrenme verimini değerlendirirken çalışma süresinin yanında tekrarların dağılımı da göz önünde bulundurulmalıdır.","İki haftadaki hata farkı, çalışma biçiminden bağımsız olarak ortaya çıkmıştır.","Öğrenci, sınavdan önce hangi konuları çalıştığını karşılaştırmamıştır."]'::jsonb, 2, 'C seçeneği, iki çalışma düzeninin ve ikinci yöntemdeki hata azalmasının birlikte değerlendirilmesinden çıkarılır. A yalnızca ilk yöntemi üstün sayar; B tekrarların olası etkisini kabul etse de genel yöntemi ifade etmez. D ve E deneyin karşılaştırmalı niteliğini bozar.', true, 'migration', NULL, '446bf1c7e3298758ddccabed1c9b3685b2d25d766645d1fb60c4efbf1bce8ff2'),
  ('v2-8-completion-02', 'completion', 'easy', '8', 'Okul koridorundaki duyuru panosu çok kalabalık görünüyordu. Öğrenciler süresi geçen ilanları kaldırıp kalanları konu başlıklarına göre ayırdı; _____.', 'Paragrafı en uygun biçimde tamamlayan cümle hangisidir?', '["öğrenciler duyuru hazırlamayı bıraktı.","bütün ilanlar gizlendi.","pano daha düzenli ve okunabilir oldu.","konu başlıkları silindi.","koridor kullanıma kapatıldı."]'::jsonb, 2, 'C seçeneği, eski ilanların kaldırılması ve sınıflandırılmasının doğal sonucudur. Diğerleri yapılan düzenlemeyle çelişir.', true, 'migration', NULL, '65ea05aa940cf8fb31b191c214274a4e08b4a5855ed02c79f8b89276b53ef5fc'),
  ('v2-8-completion-03', 'completion', 'medium', '8', 'Kamp ekibi, çadırların kurulacağı zemini seçerken yalnızca manzaraya bakmadı. Yağmurda su biriken çukurları, rüzgâr alan açıklığı ve acil çıkışa uzaklığı inceledi; _____.', 'Parçada ulaşılan sonuç göz önüne alındığında, bu parçanın sonuna hangi cümle getirilmelidir?', '["en yüksek ve en uzak noktayı seçti.","çukurları çadırların içine taşıdı.","güvenli ve ulaşılabilir alanı tercih etti.","rüzgârı artıracak bir düzen kurdu.","acil çıkışı kullanılamaz hâle getirdi."]'::jsonb, 2, 'C seçeneği, zeminin farklı riskleri incelendikten sonra beklenen kararı tamamlar. Diğerleri güvenlik ölçütlerine aykırıdır.', true, 'migration', NULL, '05732b0f3afa3792404b7ec7d52b848964816326862d6bc4c49bdf927cc9814c'),
  ('v2-8-completion-04', 'completion', 'medium', '8', 'Grafik tasarım öğrencisi, afişteki yazının uzaktan okunmadığını fark etti. Harfleri büyütmek yerine arka planla yazı arasındaki renk farkını artırdı ve başlığı sadeleştirdi; _____.', 'Paragraf aşağıdakilerden hangisiyle tamamlanırsa anlam bütünlüğü sağlanır?', '["renk farkı ortadan kalktı.","başlık tamamen görünmez hâle geldi.","afiş uzaktan daha kolay okunur oldu.","yazılar daha karmaşık seçildi.","öğrenci afişi sergilemedi."]'::jsonb, 2, 'C seçeneği, renk karşıtlığı ve sadeleştirmenin okunabilirlik sonucunu verir. Diğerleri yapılan değişikliklerin tersidir.', true, 'migration', NULL, '349d29288e4cc03cf15cfef9e3be1adfd042a05cf3021f049533308cb284b92d'),
  ('v2-8-completion-05', 'completion', 'medium', '8', 'Köy kooperatifi, ürünleri aynı gün pazara götürmekte zorlanıyordu. Üyeler hasat saatlerini ve araçların dönüş zamanını çizelgeye yazdı; _____.', 'Anlatıcının vurguladığı noktalar dikkate alındığında, bu cümle aşağıdakilerden hangisiyle tamamlanmalıdır?', '["ürünlerin bir kısmını tarlada bıraktı.","çizelgeyi kullanmayı reddetti.","taşıma planını çakışmaları azaltacak biçimde yeniden düzenledi.","araçların dönüşünü tamamen iptal etti.","hasat günlerini rastgele seçti."]'::jsonb, 2, 'C seçeneği, kayıtların taşıma planını düzenlemek için kullanılmasını tamamlar. Diğerleri kooperatifin amacına ters düşer.', true, 'migration', NULL, 'c07be2619febbe0eeaea29a18ee5edce430aab3c7e36bf3976c5a6de6f3b0413'),
  ('v2-8-completion-06', 'completion', 'medium', '8', 'Laboratuvarda öğrenciler aynı miktar suyu farklı sıcaklıklarda bekletti. Buharlaşma miktarını ölçerken kapların ağızlarını eşit tuttu; _____.', 'Verilen örnekler bir arada ele alındığında, paragrafın sonunu en iyi tamamlayan seçenek hangisidir?', '["sıcaklığı hiç kaydetmediler.","bütün kapları farklı boyutlarda seçtiler.","ölçümü etkileyebilecek kap farkını denetim altında tuttular.","suyu ölçmeden döktüler.","deneyi yalnızca bir kapla yaptılar."]'::jsonb, 2, 'C seçeneği, karşılaştırmayı adil kılmak için kap ağızlarının eşit tutulmasının anlamını açıklar. Diğerleri verilen yönteme uymaz.', true, 'migration', NULL, 'cd7fa67e11632b6b65cd4125d2796bd9e5516d31c14978d07c2e70ce36fe0e20'),
  ('v2-8-completion-07', 'completion', 'medium', '8', 'Koro, prova kayıtlarında bazı seslerin diğerlerini örttüğünü fark etti. Şef, yalnızca yüksek söyleyenleri kısmak yerine salonun yankısını, oturma düzenini ve mikrofon mesafesini ölçtü; _____.', 'Bu parçayı uygun biçimde tamamlayan cümle hangisidir?', '["sadece yüksek söyleyenlerin sesini kısmayı yeterli buldu.","salonun düzenini değiştirmeden prova süresini uzattı.","sesleri dengelemek için bütün bölümlerin yerini aynı biçimde değiştirdi.","ölçümlere dayanarak mikrofon konumu ve oturma düzeninde küçük ayarlar yaptı.","kayıtların birbirine benzemesi için yankıyı artırdı."]'::jsonb, 3, 'D seçeneği, şefin yankı, oturma düzeni ve mikrofon mesafesi ölçümlerini somut ayarlara dönüştürmesini tamamlar. A önceki tek yönlü yaklaşımı tekrarlar; B ölçülen koşulları yok sayar. C gereğinden kapsamlı, E ise sorunu artıran bir sonuç önerir.', true, 'migration', NULL, 'bec2a020b0c6564a641c02d96017b7761ab401e468e734eb903429544adff4c5'),
  ('v2-8-completion-08', 'completion', 'medium', '8', 'Şehir planlamacıları, yeni bisiklet yolunun kavşaklarda kesintiye uğradığını gördü. Kaza kayıtlarını, sürücü görüş mesafesini ve yaya geçiş saatlerini karşılaştırdı; _____.', 'Paragraf aşağıdakilerden hangisiyle tamamlanmalıdır?', '["kavşaklardaki bisiklet geçişlerini bütün araçlardan bağımsız hâle getiren bir çözüm önerdi.","yalnızca kaza kayıtlarına dayanarak yolun yönünü değiştirdi.","görüşü artıran ve yaya geçişini düzenleyen bir kavşak tasarımı önerdi.","bisiklet yolunu kaza kayıtlarının bulunmadığı başka bir bölgeye taşıdı.","yaya geçiş saatlerini tasarım kararının dışında bıraktı."]'::jsonb, 2, 'C seçeneği, kaza kayıtları, görüş mesafesi ve yaya geçiş saatlerinin kavşak tasarımına dönüştürülmesini tamamlar. A ve D sorunu tümüyle başka yere taşır; B ve E paragrafta incelenen verilerden birini dışarıda bırakır.', true, 'migration', NULL, 'ffb2583c95b1833fc0c1daa552e0c157d5299de452900197a493a4ce8bfd4367'),
  ('v2-8-flow-02', 'flow', 'easy', '8', '(I) Okul servisi duraklarının isimleri listelendi. (II) Her durağın öğrenciler için uygunluğu konuşuldu. (III) Liste, velilere görüş bildirmeleri için gönderildi. (IV) Servis bekleme alanındaki oturma banklarının sayısı belirlendi. (V) Gelen görüşlere göre iki durağın yeri yeniden değerlendirildi.', 'Servis duraklarıyla ilgili akışı bozan cümle hangisidir?', '["I","II","III","V","IV"]'::jsonb, 4, 'IV. cümle bekleme alanı banklarına geçer; I, II, III ve V durak listesinin hazırlanıp değerlendirilmesini sürdürür.', true, 'migration', NULL, 'c7cf10e111b789acd6d21f0bafd9b560767b695cb3241082b6df00183a862f69'),
  ('v2-8-flow-03', 'flow', 'easy', '8', '(I) Sınıfın enerji tüketimi bir hafta boyunca kaydedildi. (II) En çok elektriğin hangi saatlerde kullanıldığı belirlendi. (III) Kullanılmayan ışıkların kapatılması için hatırlatıcılar hazırlandı. (IV) Koridordaki prizlerin kapak renkleri yenilendi. (V) Sonraki hafta tüketim yeniden ölçüldü.', 'Enerji çalışmasının düşünce akışını bozan cümle hangisidir?', '["I","II","III","V","IV"]'::jsonb, 4, 'IV. cümle priz kapaklarının renklerine geçer; I, II, III ve V enerji ölçümü ve tasarruf önlemlerini anlatır.', true, 'migration', NULL, '46a291b0c48165b118889c5f0ad768ee6da9fc477a241d1a9cc8a98d7abae204'),
  ('v2-8-flow-04', 'flow', 'medium', '8', '(I) Nehir kıyısında suyun bulanıklığı ölçüldü. (II) Yağmurdan sonra kıyıya taşınan toprak miktarı kaydedildi. (III) Bitki örtüsünün seyrek olduğu bölümler haritada işaretlendi. (IV) Nehir kıyısındaki yürüyüş yolunun taşları numaralandırıldı. (V) Ölçümler, bitkisi az alanlarda bulanıklığın arttığını gösterdi.', 'Nehir incelemesinde akışı bozan cümle hangisidir?', '["I","II","III","V","IV"]'::jsonb, 4, 'IV. cümle yürüyüş yolu taşlarına geçer; I, II, III ve V bulanıklık ile bitki örtüsü arasındaki incelemeyi sürdürür.', true, 'migration', NULL, '4ac5ab46b8102063eef8724a2a4ea210ae5bd69bbf743cfee7586a8df01722d1'),
  ('v2-8-flow-05', 'flow', 'medium', '8', '(I) Fotoğrafçılar gökyüzünün gün doğumundaki renklerini kaydetti. (II) Aynı noktadan gün batımında yeni fotoğraflar çekildi. (III) Görsellerdeki renk tonları ölçülerek karşılaştırıldı. (IV) Fotoğrafçıların kullandığı tripodların ağırlıkları kaydedildi. (V) Karşılaştırma, ışığın gün içindeki değişimini ortaya koydu.', 'Fotoğraf çalışmasının akışını bozan cümle hangisidir?', '["I","II","III","V","IV"]'::jsonb, 4, 'IV. cümle tripodların ağırlığına geçer; I, II, III ve V gökyüzü renklerinin karşılaştırılmasını oluşturur.', true, 'migration', NULL, '051c068ed27c902d12bd7966c8717b91aba566e3e47445bfe1dd375930bc2dc4'),
  ('v2-8-flow-06', 'flow', 'medium', '8', '(I) Tarihî evin duvarlarındaki boya katmanları incelendi. (II) Her katmanın yaklaşık dönemi arşiv fotoğraflarıyla eşleştirildi. (III) Koruma ekibi, en eski katmanı görünür bırakacak alanları belirledi. (IV) Restorasyon alanının ziyaretçi yönlendirme afişleri yenilendi. (V) Restorasyon planı bu bulgulara göre hazırlandı.', 'Restorasyon sürecinde düşünce akışını bozan cümle hangisidir?', '["I","II","III","V","IV"]'::jsonb, 4, 'IV. cümle ziyaretçi afişlerine geçer; I, II, III ve V boya katmanlarından restorasyon planına ilerler.', true, 'migration', NULL, '05d5b7bbb2b54bb8cdb358d1bedf39f69568cbd14d0e2a168c04608edad89556'),
  ('v2-8-flow-07', 'flow', 'medium', '8', '(I) Göl kıyısında farklı derinliklerde su sıcaklığı ölçüldü. (II) Aynı noktalarda çözünmüş oksijen miktarı kaydedildi. (III) Ölçümler, balıkların görüldüğü bölgelerle eşleştirildi. (IV) Kıyıdaki sazlıkların mevsimsel renk değişimi fotoğraflandı. (V) Bulgular, bazı balık türlerinin serin ve oksijeni yüksek bölümlerde toplandığını gösterdi.', 'Göl ekolojisi incelemesinin mantıksal akışını bozan cümle hangisidir?', '["I","II","III","V","IV"]'::jsonb, 4, 'IV. cümle sazlıkların renk değişimine geçer; I, II, III ve V ise sıcaklık ve oksijen ölçümlerini balıkların dağılımıyla ilişkilendirerek sonuca bağlar.', true, 'migration', NULL, '82c1101d2c6a612d8ef50a93c7f57a4fce03bf8fdfaa47af3889dcec4ab83842'),
  ('v2-hs-main_idea-02', 'main_idea', 'easy', 'high-school', 'Bir üniversite kütüphanesi, öğrencilerin sessiz alan ararken katlar arasında dolaştığını gözledi. Çalışma masalarının doluluk durumunu gösteren küçük ekranlar yerleştirildi. Öğrenciler boş masayı daha hızlı buldu ve koridorlardaki gereksiz hareket azaldı.', 'Anlatıcının vurguladığı noktalar dikkate alındığında, bu parçanın ana düşüncesi aşağıdakilerden hangisidir?', '["Kütüphanelerde ekran kullanılmamalıdır.","Öğrenciler kütüphanede çalışmayı bırakmıştır.","Doluluk bilgisini görünür kılmak, ortak bir mekânın kullanımını kolaylaştırabilir.","Koridorlar çalışma masalarından daha önemlidir.","Sessiz alanlar yalnızca üst kattadır."]'::jsonb, 2, 'C seçeneği, doluluk ekranlarının boş masa bulmayı kolaylaştırıp hareketi azaltmasını özetler. Diğer seçenekler sonucu yanlış geneller.', true, 'migration', NULL, 'e38776615217527cfd3adcc303617e7319cb91b16570a72972f8d19f2850c7f8'),
  ('v2-hs-main_idea-03', 'main_idea', 'medium', 'high-school', 'Bir kentte toplu taşıma ücretleri değişirken tartışma yalnızca bilet fiyatına odaklandı. Ulaşım araştırmacıları, aktarma süresini, sefer sıklığını ve farklı gelir gruplarının yolculuk alışkanlıklarını da inceledi. Rapor, adil bir düzenlemenin tek bir rakama bakılarak tasarlanamayacağını ortaya koydu.', 'Parçanın temel savı nedir?', '["Bilet fiyatı ulaşımın tek ölçütüdür.","Aktarma süresi hiçbir yolcuyu etkilemez.","Ulaşım politikası, fiyatın yanı sıra kullanım koşulları ve farklı grupların ihtiyaçlarıyla değerlendirilmelidir.","Sefer sıklığı bilet ücretinden bağımsızdır.","Gelir grupları aynı biçimde yolculuk eder."]'::jsonb, 2, 'C seçeneği, raporun fiyatı diğer koşullar ve kullanıcı farklılıklarıyla birlikte ele alan sonucunu verir. Diğerleri incelemeyi tek bir etkene indirger.', true, 'migration', NULL, 'f3b3edfdd89bf621f8a3391471076a0b1624f4980e80cd0fc26efd9c51029f42'),
  ('v2-hs-main_idea-04', 'main_idea', 'medium', 'high-school', 'Bir arşivci, aynı yazarın mektuplarını kronolojik sıraya koyduğunda üslubundaki değişimi daha belirgin gördü. Ancak mektupların gönderildiği kişileri ve dönemin toplumsal olaylarını hesaba katmadan bu değişimi yalnızca kişisel bir dönüşüm olarak açıklamanın eksik kalacağını belirtti.', 'Bu parçanın ana düşüncesi hangi seçenekte doğru verilmiştir?', '["Mektupların kronolojisi hiçbir bilgi sağlamaz.","Yazarın üslubu hayatı boyunca aynıdır.","Üslup değişimini anlamak için metin sırası kadar iletişim bağlamı da önemlidir.","Toplumsal olaylar mektuplara yansımaz.","Arşivciler mektupları alıcılarından bağımsız inceler."]'::jsonb, 2, 'C seçeneği, kronoloji ile alıcı ve dönem bağlamının birlikte gerekliliğini özetler. Diğerleri parçadaki uyarıyı reddeder.', true, 'migration', NULL, 'a5bcd428487f45ad8a64fc53c156846e3c61f5ece5b2ea48ebea56773a2133cf'),
  ('v2-hs-main_idea-05', 'main_idea', 'medium', 'high-school', 'İklim bilimcilerinin modeli, kıyı kentindeki taşkın riskini yalnızca yağış miktarıyla açıklayamıyordu. Deniz seviyesindeki yükselme, zeminin betonlaşma oranı ve drenaj kanallarının kapasitesi modele eklendiğinde geçmiş taşkınlar daha isabetli tahmin edildi. Araştırma ekibi, karmaşık olayların çoklu değişkenlerle okunması gerektiğini vurguladı.', 'Parçanın ana düşüncesi nedir?', '["Taşkınlar yalnızca yağışla oluşur.","Modellerde değişken sayısı azaltılmalıdır.","Bir olayı daha iyi açıklamak, ilgili çevresel ve altyapısal etkenleri birlikte değerlendirmeyi gerektirebilir.","Betonlaşma taşkın riskini azaltır.","Geçmiş taşkınlar tahmin edilemez."]'::jsonb, 2, 'C seçeneği, yağış dışındaki üç değişken eklendiğinde tahminin iyileşmesini açıklar. Diğerleri araştırma sonucuyla çelişir.', true, 'migration', NULL, 'd8952f3dc4d2caf8a3e32135dafd1b48b127565af7a00c793270f942564e9a2c'),
  ('v2-hs-main_idea-06', 'main_idea', 'medium', 'high-school', 'Bir roman çevirmeni, deyimleri kelime kelime aktardığında metnin mizahının kaybolduğunu gördü. Hedef dilde benzer çağrışım yapan ifadeleri araştırdı, fakat kültürel bir ayrıntının açıklama gerektirdiği yerlerde kısa notlar kullandı. Böylece çeviri hem akıcı kaldı hem de özgün bağlamı korudu.', 'Bu parçanın temel düşüncesi aşağıdakilerden hangisidir?', '["Deyimler her dilde aynı biçimde çevrilir.","Akıcı çeviri için kültürel ayrıntılar silinmelidir.","İyi çeviri, anlamı hedef dilde doğal kılarken gerektiğinde bağlamı da korur.","Çevirmen yalnızca sözlük kullanmalıdır.","Mizah çeviride aktarılamaz."]'::jsonb, 2, 'C seçeneği, doğal ifadeler ile açıklama notlarının birlikte kullanılmasını özetler. Diğer seçenekler çevirmenin yöntemine uymaz.', true, 'migration', NULL, 'ffcd704f2b91363a2147d9a500997230acad0dd83fd8969e7422da3664fda9f0'),
  ('v2-hs-main_idea-07', 'main_idea', 'medium', 'high-school', 'Üniversite kulübü, gönüllü katılımının düşük olmasını öğrencilerin ilgisizliğiyle açıklıyordu. Yeni bir anket, toplantıların ders saatleriyle çakıştığını ve duyuruların geç yapıldığını gösterdi. Kulüp zamanlamayı değiştirip duyuru takvimini erkene alınca katılım arttı.', 'Parçada vurgulanan düşünce nedir?', '["Gönüllülük yalnızca ilgiyle belirlenir.","Duyurular etkinlikten sonra yapılmalıdır.","Ders saatleri etkinlikleri etkilemez.","Katılım sorunlarını anlamak için kişisel yargı yerine koşulları incelemek gerekir.","Katılım artışı rastlantıdır."]'::jsonb, 3, 'D seçeneği, ilk yargının koşullar incelenince değişmesini ve düzenlemelerin sonuç vermesini açıklar. Diğerleri kanıtla desteklenmez.', true, 'migration', NULL, '828948c9a8bb2ab8294260265e9236ad19aa790c310eb50aa5c72f79d71b5415'),
  ('v2-hs-main_idea-08', 'main_idea', 'medium', 'high-school', 'Bir sağlık iletişimi kampanyası, yalnızca risk oranlarını vermenin davranış değişikliği yaratmadığını fark etti. Mesajlar, insanların günlük hayatında uygulayabileceği küçük adımları ve bu adımların neden önemli olduğunu gösteren örneklerle yeniden hazırlandı. İzleyen aylarda danışma hattına gelen sorular daha somut hâle geldi.', 'Anlatılan gelişmeler dikkate alındığında, bu parçanın ana düşüncesi hangi seçenekte verilmiştir?', '["Oranlar ne kadar yüksekse mesaj o kadar etkilidir.","Danışma hattı yalnızca uzmanlar içindir.","Kampanyalar davranışları değiştiremez.","Sağlık iletişiminde uygulanabilir örnekler, soyut risk bilgilerinin etkisini artırabilir.","Günlük adımlar risk oranlarını gizler."]'::jsonb, 3, 'D seçeneği, soyut oranlara uygulanabilir adımlar eklenmesinin iletişimi güçlendirdiğini özetler. Diğerleri kampanyanın sonucunu tersine çevirir.', true, 'migration', NULL, 'b4cbc9dc97e283fdeef5390fe020e4ba1ed42c2391766b6f03b7e5d4558602de'),
  ('v2-hs-main_idea-09', 'main_idea', 'medium', 'high-school', 'Bir edebiyat dergisi, genç yazarların metinlerini değerlendirirken yalnızca dilbilgisi hatalarını işaretlememeye karar verdi. Editörler anlatıcı seçimini, olayların ritmini ve metnin okurda oluşturduğu etkiyi de tartıştı. Yazarlar, hangi düzeltmenin metnin amacına hizmet ettiğini açıklayan geri bildirimlerle yeniden yazdı.', 'Bu metnin verdiği bilgiler ışığında, parçanın ana düşüncesi aşağıdakilerden hangisidir?', '["Metin değerlendirmesi yalnızca yazım denetiminden ibarettir.","Ritim ve anlatıcı seçimi yazıyla ilgili değildir.","Editör geri bildirimi yazarı sınırlar.","Bir yazıyı geliştirmek için biçimsel doğruluk kadar anlatım tercihlerini ve amacı da ele almak gerekir.","Yeniden yazmak metni mutlaka kötüleştirir."]'::jsonb, 3, 'D seçeneği, derginin dilbilgisini anlatım amacı ve yapı ile birlikte değerlendirmesini verir. Diğerleri yaklaşımı daraltır.', true, 'migration', NULL, '0da3b284bf05202cbdd41f29e38aa11776e88268f846b29163f9607873b2aef9'),
  ('v2-hs-main_idea-10', 'main_idea', 'medium', 'high-school', 'Bir şirket, uzaktan çalışma verimliliğini yalnızca çevrim içi geçirilen saatlerle ölçtü ve ilk raporda artış ilan etti. Çalışanların tamamlanan iş sayısı, toplantı yoğunluğu ve evdeki çalışma koşulları incelendiğinde bazı ekiplerin daha uzun çevrim içi kaldığı hâlde daha az iş bitirdiği görüldü. Şirket ölçütlerini çıktı ve koşulları kapsayacak biçimde yeniledi.', 'Bu parçanın ana düşüncesi nedir?', '["Çevrim içi kalma süresi, ekiplerin iş yükünü karşılaştırmada yararlı bir başlangıç göstergesidir.","Toplantı yoğunluğu, tamamlanan iş sayısından daha güvenilir bir verimlilik ölçüsüdür.","Verimlilik ölçümü, geçirilen süreyi çıktılar ve çalışma koşullarıyla birlikte değerlendirmelidir.","Ev koşulları hesaba katıldığında çevrim içi süre göstergesi tamamen geçersiz olur.","Tamamlanan iş sayısı, çalışma süresinden bağımsız olarak tek başına yeterli ölçüttür."]'::jsonb, 2, 'C seçeneği, çevrim içi süre ölçütünün tamamlanan işler, toplantı yoğunluğu ve ev koşullarıyla birlikte yeniden değerlendirilmesi gerektiğini özetler. A gerçek bir başlangıç verisini yeterli sonuca dönüştürür; B tek bir alternatifi üstün sayar. D ve E ise ölçümü başka bir tek ölçüte indirger.', true, 'migration', NULL, '14122e4ce3db3054f231400d061d2628c1e28c01bacbff17a8a916b9cd1f2596'),
  ('v2-hs-supporting_idea-02', 'supporting_idea', 'easy', 'high-school', 'Fotoğraf sergisinde her eserin yanında çekildiği yıl ve kullanılan makine yazıyordu. Ziyaretçiler, aynı manzaranın farklı yıllarda nasıl göründüğünü bu bilgiler sayesinde karşılaştırdı.', 'Eserlerin yanındaki bilgilerin sağladığı kolaylık nedir?', '["Fotoğrafları gizlemek","Manzaraları değiştirmek","Sergiyi kısaltmak","Görüntüleri zaman ve araç bakımından karşılaştırmak","Makine kullanımını yasaklamak"]'::jsonb, 3, 'D seçeneği, yıl ve makine bilgilerinin karşılaştırmaya imkân verdiğini belirtir. Diğerleri metinde amaç olarak verilmez.', true, 'migration', NULL, 'c51800d892ef1b51e918a52de1e099f2661db1ecba7a2eedf69be75a688d60fc'),
  ('v2-hs-supporting_idea-03', 'supporting_idea', 'easy', 'high-school', 'Kampüs bisikletlerinin gidonuna küçük reflektörler takıldı. Akşam denemesinde araç sürücüleri bisikletlileri daha erken fark etti; güvenlik birimi reflektörlerin düzenli kontrolünü önerdi.', 'Akşam denemesinde hangi sonuç gözlenmiştir?', '["Bisikletler daha hızlı gitmiştir.","Güvenlik birimi bisikletleri toplamıştır.","Reflektörler çıkarılmıştır.","Sürücülerin bisikletlileri fark etme süresi kısalmıştır.","Akşam denemesi yapılmamıştır."]'::jsonb, 3, 'D seçeneği, reflektörlerin görünürlüğü artırdığı gözlemini aktarır. Diğer seçenekler metne aykırıdır.', true, 'migration', NULL, '7112c6134e03f8748859a084eb08a9c4f6821fc4f0ecd64d803b7c4c6eb37603'),
  ('v2-hs-supporting_idea-04', 'supporting_idea', 'easy', 'high-school', 'Bir tarih podcast''inde sunucu, arşiv belgesini okurken belgenin kimin tarafından ve hangi amaçla yazıldığını da açıkladı. Dinleyiciler böylece belgede yer alan bilgileri tarafsız bir liste olarak değil, belirli bir bağlamın ürünü olarak değerlendirdi.', 'Sunucunun verdiği ek bilgi ne işe yaramıştır?', '["Belgeyi tarihsiz bırakmıştır.","Podcast''i yalnızca müziğe dönüştürmüştür.","Belgedeki bütün bilgileri geçersiz kılmıştır.","Belgenin oluştuğu amacı ve bakış açısını değerlendirmeye yardımcı olmuştur.","Dinleyicilerin soru sormasını engellemiştir."]'::jsonb, 3, 'D seçeneği, yazar ve amaç bilgisinin kaynağı bağlam içinde değerlendirmeyi sağladığını açıklar. Diğerleri bu işlevi karşılamaz.', true, 'migration', NULL, 'd815dcc4158346a40406ed0f564e88ab9d1651e1a7b860aea80e3f75994f25c4'),
  ('v2-hs-supporting_idea-05', 'supporting_idea', 'easy', 'high-school', 'Laboratuvar raporunda araştırmacılar ölçüm sonuçlarının yanında hata payını da verdi. Bir değerin diğerinden biraz yüksek olmasına rağmen hata aralıklarının kesiştiğini belirterek kesin üstünlük iddiasından kaçındılar.', 'Hata payının rapora eklenmesinin nedeni nedir?', '["Bütün ölçümleri eşit göstermek","Değerleri gizlemek","Deneyi tekrarlamamak","Yakın sonuçların belirsizliğini dürüstçe belirtmek","Hata aralıklarını büyütmek"]'::jsonb, 3, 'D seçeneği, kesişen hata aralıklarının kesin üstünlük yorumunu sınırladığını söyler. Diğerleri bilimsel raporlama amacına aykırıdır.', true, 'migration', NULL, 'd3d7519c4a6fa0350dbaef219f31060d2f2085bc88ef06fac80c3b5366f12f4b'),
  ('v2-hs-supporting_idea-06', 'supporting_idea', 'easy', 'high-school', 'Bir şehir tiyatrosu, bilet fiyatlarını belirlerken yalnızca salon kapasitesine bakmadı. Öğrenciler için indirimli kontenjan, hafta içi doluluk ve yapım maliyetlerini birlikte değerlendirdi. Yeni tarife, düşük talep gören günlerde seyirci sayısını artırdı.', 'Yeni tarifenin oluşmasında hangi ayrıntılar birlikte ele alınmıştır?', '["Yalnızca koltuk sayısı","Sahne ışıklarının rengi","Oyuncuların yaşları","İndirim, doluluk ve maliyet verileri","Seyircilerin ulaşım araçları"]'::jsonb, 3, 'D seçeneği, tarifede sayılan üç ölçütü birlikte verir. Diğer ayrıntılar metinde yer almaz.', true, 'migration', NULL, '02b6cc70228382fdec4182cc616166ce67da4ec4cf26353ec56ef023de9ba67d'),
  ('v2-hs-supporting_idea-07', 'supporting_idea', 'easy', 'high-school', 'Bir derste öğrenciler, yapay zekâ tarafından özetlenen bir makaleyi özgün metinle karşılaştırdı. Özetin ana savı koruduğunu, ancak iki sınırlayıcı koşulu dışarıda bıraktığını saptadılar. Öğretmen, özetleri kullanırken eksilen koşulların ayrıca kontrol edilmesini istedi.', 'Öğretmenin uyarısını destekleyen ayrıntı hangisidir?', '["Özet özgün metinden uzundur.","Yapay zekâ hiçbir cümle üretmemiştir.","Öğrenciler özgün metni okumamıştır.","Özet, ana savı korurken sınırlayıcı koşulları atlamıştır.","Koşullar makalenin dışında verilmiştir."]'::jsonb, 3, 'D seçeneği, uyarının nedenini oluşturan somut bulgudur. Diğerleri karşılaştırma sonucunu yanlış aktarır.', true, 'migration', NULL, 'ea788dc3d222e743885c6a4944b4446332a5860956c2ed2ae30a368fda91754c'),
  ('v2-hs-supporting_idea-08', 'supporting_idea', 'easy', 'high-school', 'Bir danışmanlık raporunda aynı öneri üç farklı maliyet senaryosuyla sunuldu. Her senaryoda hangi varsayımın değiştiği tabloya yazıldı; okuyucu, önerinin hangi koşulda uygulanabilir olduğunu görebildi.', 'Tabloda varsayımların belirtilmesi ne sağlamıştır?', '["Senaryoları birbirinden gizlemeyi","Tek bir sonucu zorunlu kılmayı","Maliyetleri tamamen kaldırmayı","Önerilerin hangi koşullarda geçerli olduğunu görmeyi","Raporu sayısal verilerden arındırmayı"]'::jsonb, 3, 'D seçeneği, varsayım değişikliklerinin uygulanabilirlik koşullarını görünür kılmasını açıklar. Diğerleri tablo işlevinin tersidir.', true, 'migration', NULL, '5b434f0cfdcce93d58e94d457e1d472c158da2ec361aec8578fb9b95be5d82cc'),
  ('v2-hs-supporting_idea-09', 'supporting_idea', 'medium', 'high-school', 'Bir haber sitesi, anket sonucunu ''toplumun çoğu böyle düşünüyor'' başlığıyla yayımladı. Veri ekibi örneklemin yalnızca bir şehirde yaşayan ve çevrim içi ankete katılan kişilerden oluştuğunu, yaş dağılımının da dengeli olmadığını belirledi. Başlık, bu sınırlılıklar eklenerek yeniden yazıldı.', 'Başlığın yeniden yazılmasını gerektiren temel ayrıntı hangisidir?', '["Örneklemin tek şehirle sınırlı olması başlıkta şehir bilgisinin ayrıca verilmesini gerektirir.","Yaş dağılımının dengeli olmaması, gruplar arasındaki karşılaştırmayı zayıflatır.","Çevrim içi katılımın bulunması, anketin bütünüyle geçersiz olduğunu gösterir.","Örneklemin dar ve dengesiz olması nedeniyle sonucun tüm topluma genellenememesi","Başlığın yeniden yazılması, anketteki soruların uzunluğundan kaynaklanır."]'::jsonb, 3, 'D seçeneği, tek şehirden ve dengeli olmayan yaş dağılımından oluşan örneklemin toplumun tamamını temsil etmediğini kapsar. A ve B gerçek sınırlılıkları belirtir, ancak genelleme sorununu tek başına bütünüyle açıklamaz. C ve E metinde desteklenmez.', true, 'migration', NULL, 'fb9addb328a1f43e0deb8d5aa3c0922f9e52711b696853350709f5168ef1349f'),
  ('v2-hs-inference-02', 'inference', 'easy', 'high-school', 'Kulüp toplantısında konuşma sırası için bir zamanlayıcı kullanıldı. Daha önce sözünü tamamlayamayan öğrenciler, bu uygulamayla düşüncelerini daha kısa ve düzenli ifade etti.', 'Bu uygulamadan hangi sonuç çıkarılabilir?', '["Toplantıda hiç konuşulmamıştır.","Öğrenciler düşüncelerini yazılı vermiştir.","Zamanlayıcı yalnızca başkanı ilgilendirir.","Süre sınırı, katılımı daha dengeli hâle getirebilir.","Konuşma sırası kaldırılmıştır."]'::jsonb, 3, 'D seçeneği, zamanlayıcının konuşma fırsatlarını dengelediği gözleminden çıkarılır. Diğerleri metinde yoktur.', true, 'migration', NULL, '5f42926395e3383116c26dbe2b18d5a4540d8fd233eb3333b62390571c2ac07d'),
  ('v2-hs-inference-03', 'inference', 'medium', 'high-school', 'Bir araştırmacı, şiirlerdeki ''gece'' sözcüğünün geçtiği dizeleri işaretledi. Sözcüğün bazı şiirlerde yalnızlığı, bazılarında ise dinlenmeyi anlattığını gördü; anlamı tek bir karşılığa indirmeden her şiirin bağlamını inceledi.', 'Araştırmacının yönteminden hangi çıkarım yapılabilir?', '["Bir sözcük her metinde aynı anlamı taşır.","''Gece'' yalnızca zaman bildirir.","Şiirlerde bağlam önemsizdir.","Sözcük anlamını belirlemek için kullanıldığı bağlam dikkate alınmalıdır.","Araştırmacı dizeleri işaretlememiştir."]'::jsonb, 3, 'D seçeneği, aynı sözcüğün farklı bağlamlarda farklı anlamlar taşımasından çıkarılır. Diğerleri bulguyla çelişir.', true, 'migration', NULL, '558dd1c4d0f637e14a8d5f4b8c8c47c7c98b0de437d05f268200eec7dc38d8f7'),
  ('v2-hs-inference-04', 'inference', 'medium', 'high-school', 'Bir şehir, yeni tramvay hattının gürültüsünü değerlendirmek için hattın yanındaki ve uzaktaki binalarda ölçüm yaptı. Gündüz değerleri birbirine yakındı, fakat gece hattın yanındaki binalarda fark büyüdü. Belediye gece seferlerinin hızını ve bakım saatlerini yeniden planladı.', 'Belediyenin plan değişikliğinden hangi çıkarım yapılabilir?', '["Gürültü yalnızca uzaktaki binalarda duyulur.","Ölçümler gündüz yapılmamıştır.","Gece seferleri tamamen kaldırılmıştır.","Gürültünün zaman ve mesafeye göre değiştiği dikkate alınmıştır.","Bakım saatleri gürültüyü etkilemez."]'::jsonb, 3, 'D seçeneği, ölçümlerde görülen zaman ve mesafe farkının planlamaya yansıdığını çıkarır. Diğerleri metindeki değişimi yanlış yorumlar.', true, 'migration', NULL, '047d4ddd77e60b0c0c89680891b4086e8d0b5db6efd85fc76d7eab1a6d58bc4b'),
  ('v2-hs-inference-05', 'inference', 'hard', 'high-school', 'Bir ekonomi yazısı, işsizlik oranı düşerken yeni işlerin çoğunun kısa süreli olduğunu belirtti. Yazar, yalnızca orandaki düşüşe bakmanın istihdamın niteliğini göstermeyeceğini; ücret, süre ve sosyal güvence verilerinin de incelenmesi gerektiğini savundu.', 'Yazarın savından hangi sonuç çıkarılabilir?', '["İşsizlik oranındaki düşüş, istihdam miktarında bir iyileşme bulunduğuna işaret edebilir.","Kısa süreli işlerin artması, ücret ve sosyal güvence bilgilerinin incelenmesini gerekli kılar.","İşsizlik oranı ile işlerin niteliği birbirinden tamamen bağımsızdır.","İstihdamdaki nicel iyileşme, işlerin niteliği değerlendirilmeden yeterli bir gösterge değildir.","Orandaki düşüş, yeni işlerin çalışanlar için her bakımdan olumlu olduğunu gösterir."]'::jsonb, 3, 'D seçeneği, oran düşse bile ücret, süre ve sosyal güvence incelenmeden istihdamın niteliği hakkında yeterli sonuca varılamayacağını ifade eder. A ve B metindeki gerçek ayrıntıları kullanır, ancak yazarın temel uyarısını tam kapsamaz. C ve E gereğinden geniş sonuçlar çıkarır.', true, 'migration', NULL, '15babaea033605ce811352c4ff9698ee90c66ff130074f04d18cb4d30537c8b6'),
  ('v2-hs-inference-06', 'inference', 'hard', 'high-school', 'Bir romanda anlatıcı, çocukluk anılarını aktarırken bazı tarihleri karıştırdığını kabul eder. Buna rağmen aynı evin kokusunu ve sesini ayrıntılı biçimde hatırlar. Okur, anlatıcının güvenilirliğini ya tamamen reddetmek ya da bütünüyle kabul etmek yerine, anıların farklı türde doğruluklar taşıyabileceğini düşünmeye yönelir.', 'Bu parçadan hangi çıkarım yapılabilir?', '["Anlatıcının duyusal ayrıntıları doğru hatırlaması, tarih hatalarının önemsiz olduğunu kanıtlar.","Tarihler karışsa da anlatıcının evle ilgili bütün ayrıntıları nesnel olarak doğrudur.","Anlatıcının belleği, olayların kronolojisinde yanılabilirken bazı duyusal izleri koruyabilir.","Anlatıcının güvenilirliği ya bütünüyle kabul edilmeli ya da bütünüyle reddedilmelidir.","Duyusal anılar, tarih bilgisine göre daha az güvenilirdir."]'::jsonb, 2, 'C seçeneği, tarihlerin karışması ile evin kokusu ve sesinin ayrıntılı hatırlanmasını birlikte yorumlar. A ve B duyusal hatırlamadan gereğinden geniş bir doğruluk sonucu çıkarır; D yanlış bir ikilik kurar. E ise paragrafın duyusal izlerin korunabildiği yönündeki çıkarımını tersine çevirir.', true, 'migration', NULL, 'c8ae40a005fec896514dd2dc559acbbeda341e4899e307ee9f47b877337e1702'),
  ('v2-hs-inference-07', 'inference', 'hard', 'high-school', 'Bir üniversite, çevrim içi derslerde kamerayı açma zorunluluğunu kaldırdı. Katılım sayısı artmış görünse de sözlü tartışmalara katkı azaldı; erişim kayıtları, bazı öğrencilerin dersi yalnızca arka planda açık tuttuğunu gösterdi. Değerlendirme sistemi, görünürlük yerine kısa tartışma notları ve görev teslimlerini de içerecek biçimde değiştirildi.', 'Değerlendirme sistemindeki değişiklik hangi çıkarıma dayanır?', '["Kamera görüntüsü, çevrim içi derste bulunmaya ilişkin bir belirti sağlayabilir.","Erişim kayıtları öğrencinin derse bağlandığını gösterir, ancak dikkatini kanıtlamaz.","Kısa tartışma notları, katılımı ölçmek için tek başına yeterlidir.","Katılımı ölçmek için görünürlük dışındaki etkinlik göstergeleri de gereklidir.","Kameranın kaldırılması, sözlü tartışmalara katkının neden azaldığını tek başına açıklar."]'::jsonb, 3, 'D seçeneği, kamera görünürlüğü ile gerçek katılım arasındaki farkın görülmesi ve görev teslimleriyle tartışma notlarının eklenmesinden çıkarılır. A ve B kamera ile erişim verilerinin sınırlı ama ilgili ipuçları olduğunu söyler; C tek bir göstergiyi yeterli sayar. E ise neden konusunda kanıtlanmamış bir kesinlik kurar.', true, 'migration', NULL, '572123fc1b77558d5193d7751e7ef4c03cbe3b5e7745dfb800d234f09f5f0067'),
  ('v2-hs-inference-08', 'inference', 'medium', 'high-school', 'Bir biyolog, aynı tür iki kelebeğin kanat desenlerini farklı sıcaklıklarda yetişen larvalarda karşılaştırdı. Desenler değişse de değişimin yönü her popülasyonda aynı değildi; biyolog, çevre etkisinin genetik farklılıklarla birlikte değerlendirilmesi gerektiğini yazdı.', 'Biyoloğun sonucundan hangi çıkarım yapılabilir?', '["Aynı sıcaklık değişimi her popülasyonda aynı desen sonucunu doğurur.","Desen değişiminin farklı yönlerde olması, sıcaklık etkisinin yalnızca bir popülasyonda görüldüğünü gösterir.","Çevre etkisi ile genetik özellikleri birbirinden ayırmak araştırmada gereksizdir.","Çevresel etkinin sonucu, popülasyonların genetik özelliklerine göre değişebilir.","Larvaların yetiştiği sıcaklık, kanat desenleriyle ilişkilendirilemez."]'::jsonb, 3, 'D seçeneği, desen değişiminin popülasyonlarda aynı yönde olmamasını ve biyoloğun çevre-genetik birlikteliği vurgusunu birlikte yorumlar. B, farklı yönlerdeki değişimi yalnızca sıcaklık etkisinin tek bir popülasyonda görülmesine bağlar; oysa biyolog genetik farklılıkların da hesaba katılması gerektiğini söyler. A, C ve E araştırma bulgusuyla uyuşmaz.', true, 'migration', NULL, 'cbfc4b911442eb93ee6ecdee36a6424f399795f172322917b53bb2126b339fe8'),
  ('v2-hs-inference-09', 'inference', 'hard', 'high-school', 'Bir mahkeme kararını inceleyen hukuk öğrencisi, sonuç bölümünü okumadan önce tarafların iddialarını ve mahkemenin dayandığı kanıtları ayrı ayrı çıkardı. Sonuçla gerekçenin aynı yöne işaret etmediği bir noktayı fark edince kararın yalnızca hüküm cümlesiyle anlaşılamayacağını savundu.', 'Öğrencinin yönteminden hangi çıkarım yapılabilir?', '["Bir kararın sonuç bölümü, gerekçeyi anlamak için önemli bir başlangıç noktasıdır.","Tarafların iddiaları ve mahkemenin kanıtları, hükmün nasıl oluştuğunu açıklayabilir.","Kararı anlamada yalnızca gerekçenin ayrıntılarını izlemek yeterlidir.","Hüküm ile gerekçe arasındaki ilişkiyi görmek için iddia ve kanıtların izlenmesi gerekir.","Sonuç ile gerekçe farklılaştığında tarafların iddiaları kararın dışında kalır."]'::jsonb, 3, 'D seçeneği, öğrencinin sonuçtan önce iddiaları ve kanıtları ayrı ayrı izlemesinin gerekçesini açıklar. A ve B ilgili unsurları belirtir, ancak yöntemin hüküm-gerekçe ilişkisini kuran bütününü vermez. C ve E öğrencinin savını daraltır ya da tersine çevirir.', true, 'migration', NULL, '396f0e84698e91c278f4d57d726abbc25c2cda1e25ebdb6265a9c45446f28a08'),
  ('v2-hs-completion-02', 'completion', 'easy', 'high-school', 'Üniversite laboratuvarında öğrenciler deney notlarını aynı başlıklar altında topladı. Böylece _____.', 'Paragrafı uygun biçimde tamamlayan cümle hangisidir?', '["ölçümler kayboldu.","not tutmaya gerek kalmadı.","başlıklar deneyden çıkarıldı.","sonuçları farklı deneyler arasında karşılaştırmak kolaylaştı.","laboratuvar kapatıldı."]'::jsonb, 3, 'D seçeneği, ortak başlıkların karşılaştırma kolaylığı sağlamasını tamamlar. Diğerleri düzenlemenin amacına aykırıdır.', true, 'migration', NULL, 'bb6f8e84be9bf82e928180c717f16a585d3a4a198e6d6b59d897469d3fce3810'),
  ('v2-hs-completion-03', 'completion', 'medium', 'high-school', 'Bir belgesel ekibi, röportaj sorularını çekimden önce denedi. Bazı soruların iki farklı konuyu aynı anda sorduğunu fark edip onları ayırdı; _____.', 'Verilen örnekler bir arada ele alındığında, bu parçanın sonuna hangi cümle getirilmelidir?', '["çekimi sorular olmadan yaptı.","soruların tamamını cevapsız bıraktı.","konukların konu dışına çıkmasını istedi.","röportajda cevapların daha açık olması için soruları yeniden düzenledi.","aynı iki konuyu tek soruda birleştirdi."]'::jsonb, 3, 'D seçeneği, deneme sonrası soruları ayırmanın açık cevap alma amacını tamamlar. Diğerleri yapılan düzeltmeyle çelişir.', true, 'migration', NULL, 'abea9090c7aa73e481f5e9351b1d857571bf087c7899170a1d7b8fce47d111ca'),
  ('v2-hs-completion-04', 'completion', 'medium', 'high-school', 'Bir şehir plancısı, meydandaki oturma alanlarını tasarlarken yalnızca estetik çizimlere bakmadı. Güneşin gün içindeki yönünü, yaya akışını ve engelli erişimini harita üzerinde işaretledi; _____.', 'Parçadaki uygulama ve sonuçlar düşünüldüğünde, paragraf aşağıdakilerden hangisiyle tamamlanmalıdır?', '["erişim yollarını daralttı.","haritaları kullanmayı bıraktı.","yaya akışını meydandan kaldırdı.","oturma alanlarını bu üç koşulu dengeleyecek biçimde yerleştirdi.","güneş yönünü hesaba katmadı."]'::jsonb, 3, 'D seçeneği, plancının üç veriyi tasarıma dönüştürmesini tamamlar. Diğerleri çalışma yönteminin tersidir.', true, 'migration', NULL, '527e01dac4552c85214da1b90e47a6540e6346e9a9deb8781bef0499b4218017'),
  ('v2-hs-completion-05', 'completion', 'medium', 'high-school', 'Bir araştırma makalesinde yazar, ilk hipotezinin deney sonuçlarıyla tam örtüşmediğini belirtti. Beklenmeyen bulguları dışlamak yerine yeni bir açıklama önerdi ve _____.', 'Bu cümlenin en uygun devamı hangisidir?', '["verileri hipoteze uydurmak için değiştirdi.","hipotezini kanıtlanmış ilan etti.","beklenmeyen sonuçları rapordan çıkardı.","deneyi tekrarlamayı gereksiz buldu.","açıklamanın başka deneylerle sınanması gerektiğini vurguladı."]'::jsonb, 4, 'E seçeneği, yeni açıklamanın sınanabilir tutulmasını tamamlar. Diğerleri bilimsel tutuma aykırıdır.', true, 'migration', NULL, 'a9e761f66f23851ad6d4c2bc89089856e0cb5e2a87f9b1d7a8aef41b9777bbd2'),
  ('v2-hs-completion-06', 'completion', 'medium', 'high-school', 'Bir tarihçi, salgın dönemine ait günlükleri incelerken yazarların hastalıkla ilgili korkularını ve o günkü bilgi sınırlarını ayrı ayrı not etti. Günlüklerdeki yanlış tahminleri bugünkü bilgilerle düzeltmek yerine, dönemin koşulları içinde açıklamaya çalıştı; _____.', 'Paragrafın sonuna hangi cümle getirilmelidir?', '["böylece günlüklerdeki tahminleri dönemin bilgi sınırları içinde yorumladı.","böylece geçmişteki yanlış tahminleri bugünkü ölçütlerle geçersiz ilan etti.","böylece yazarların korkularını gerçek olaylardan bağımsız saydı.","böylece bugünkü bilgilerle eski yazarları düzeltmeyi sürdürdü.","böylece günlükleri yalnızca kişisel duyguların kaydı olarak değerlendirdi."]'::jsonb, 0, 'A seçeneği, tarihçinin yanlış tahminleri dönemin bilgi sınırları içinde açıklama çabasını doğrudan tamamlar. B ve D, kaçınılan anakronik değerlendirmeyi geri getirir; C ve E ise günlüklerin bağlamını gereğinden fazla daraltır.', true, 'migration', NULL, '2728b6834b7f5ad2a9c6eb5d2bc8db82f6a47c7ae036b3368276ecf8fb4f1c0f'),
  ('v2-hs-completion-07', 'completion', 'medium', 'high-school', 'Bir veri gazetecisi, grafik başlığının eksen ölçeği nedeniyle küçük farkları büyük gösterdiğini fark etti. Ölçeği sıfırdan başlatıp farkın gerçek büyüklüğünü ayrıca açıklamayı seçti; _____.', 'Bu paragraf aşağıdakilerden hangisiyle tamamlanır?', '["grafiğin görsel etkisini artırmak için eksen aralığını daha da daralttı.","ölçeği sıfırdan başlatmanın küçük farkların görünüşünü azaltabileceğini dikkate aldı.","verileri açıklama eklemeden aynı grafik üzerinde bıraktı.","okurun yalnızca görsel yüksekliğe bakarak karar vermesini bekledi.","okurun görsel izlenim ile sayısal farkı karıştırmasını önlemeye çalıştı."]'::jsonb, 4, 'E seçeneği, ekseni sıfırdan başlatma ve gerçek farkı açıklama kararının okuru yanıltmama amacını tamamlar. B kullanılan yöntemin bir etkisini anlatır ancak gazetecinin iletişim amacını tam vermez; A, C ve D bu amaca ters düşer.', true, 'migration', NULL, 'acadef40f1528ccb12d4f384c2c1f68256b5f8a0b4ce4b1cc1c2ff05a02e4037'),
  ('v2-hs-completion-08', 'completion', 'medium', 'high-school', 'Bir romanın farklı baskılarında aynı bölümün noktalama işaretleri değişmişti. Editör, değişikliği doğrudan hata saymadan dönemin yazım alışkanlıklarını ve yayınevinin müdahale notlarını karşılaştırdı; _____.', 'Anlatılan gelişmeler dikkate alındığında, paragrafı en uygun biçimde tamamlayan seçenek hangisidir?', '["noktalama farklarının dönemin yazım alışkanlıklarıyla ilişkili olabileceğini belirtti.","yayınevinin müdahale notlarının her baskı için aynı sonucu verdiğini varsaydı.","anlam değişmediği sürece baskılar arasındaki farkları kayda değer bulmadı.","noktalama işaretlerinin metin anlamını etkileyemeyeceğini savundu.","baskılar arasındaki farkın metnin anlamını nasıl etkilediğini gerekçeli biçimde açıkladı."]'::jsonb, 4, 'E seçeneği, dönem alışkanlıkları ve müdahale notlarının karşılaştırılmasını metnin anlamına ilişkin gerekçeli bir sonuca bağlar. A incelemenin olası ara bulgusudur; B, C ve D editörün karşılaştırmalı yöntemini daraltır veya reddeder.', true, 'migration', NULL, 'f9650a0bd5eb23b2586f90ad001a60493a4db62b62a4fd9019942a15364c341c'),
  ('v2-hs-completion-09', 'completion', 'medium', 'high-school', 'Bir psikoloji çalışmasında katılımcılar, anket sorularının sırasının cevaplarını etkileyebileceğini belirtti. Araştırmacılar soruların sırasını farklı gruplarda değiştirip sonuçları karşılaştırdı; _____.', 'Bu cümle aşağıdakilerden hangisiyle tamamlanırsa anlam bütünlüğü sağlanır?', '["soru sırasının etkisini araştırmadan cevapları tek bir grupta topladılar.","farklı sıralardan gelen sonuçları karşılaştırmanın tek başına yeterli olduğunu düşündüler.","sıra değiştiğinde sonuçların da mutlaka değişmesi gerektiğini kabul ettiler.","anket sırasındaki değişikliği, bulguları yorumlarken göz ardı ettiler.","soru sırasının etkisini denetleyerek bulguların güvenilirliğini artırdılar."]'::jsonb, 4, 'E seçeneği, soruların sırasını farklı gruplarda değiştirip sonuçları karşılaştırmanın karıştırıcı sıra etkisini denetleme amacını tamamlar. B karşılaştırmayı tek başına yeterli sayar; A ve D denetimi yok sayar. C ise değişimin zorunlu olduğunu varsayar.', true, 'migration', NULL, '85d9ad4408ec0d9d4846d381715c15482b6893dae1f62c673b3d6001db9d4330'),
  ('v2-hs-flow-02', 'flow', 'easy', 'high-school', '(I) Üniversite bahçesindeki ağaçların gölge alanları haritalandı. (II) Öğrencilerin bu alanlarda geçirdiği süreler kaydedildi. (III) Harita ve süre kayıtları birlikte değerlendirildi. (IV) Kampüs bahçesindeki bisiklet park yerleri numaralandırıldı. (V) Sonuçlar, hangi gölge alanların daha çok kullanıldığını gösterdi.', 'Kampüs gölge alanlarıyla ilgili akışı bozan cümle hangisidir?', '["I","II","III","V","IV"]'::jsonb, 4, 'IV. cümle bisiklet park yerlerine geçer; I, II, III ve V gölge alanlarını ölçüp kullanımını değerlendirme zincirini sürdürür.', true, 'migration', NULL, '7c9c3ee20dac982f736d86fbb9a2e483d938f6f0b25a25589312bfdb2707677e'),
  ('v2-hs-flow-03', 'flow', 'easy', 'high-school', '(I) Kütüphane veri tabanında konu başlıkları güncellendi. (II) Eski başlıklarla yapılan aramaların sonuçları test edildi. (III) Eksik kayıtlar yeni anahtar sözcüklerle eşleştirildi. (IV) Kütüphane kullanıcı kartlarının son kullanım tarihleri listelendi. (V) Güncelleme sonrasında arama sonuçlarının isabeti yeniden ölçüldü.', 'Veri tabanı çalışmasında akışı bozan cümle hangisidir?', '["I","II","III","V","IV"]'::jsonb, 4, 'IV. cümle kullanıcı kartlarına geçer; I, II, III ve V veri tabanını güncelleme ve test etme sürecini anlatır.', true, 'migration', NULL, '9803f5550bf439d7655049d05efc38984d478f5fe248b660708c573f553753a0'),
  ('v2-hs-flow-04', 'flow', 'medium', 'high-school', '(I) Şehir arşivindeki haritalar taranarak dijitalleştirildi. (II) Haritalardaki sokak adları güncel kayıtlarla karşılaştırıldı. (III) Adı değişen sokaklar için tarih aralıkları belirlendi. (IV) Arşiv binasının ziyaretçi kafesindeki masa düzeni çizildi. (V) Dijital haritalar, kentin büyüme yönünü inceleyen araştırmacılara açıldı.', 'Harita arşivinin düşünce akışını bozan cümle hangisidir?', '["I","II","III","V","IV"]'::jsonb, 4, 'IV. cümle kafe masa düzenine geçer; I, II, III ve V haritaların dijitalleştirilip araştırmaya açılmasını oluşturur.', true, 'migration', NULL, '45d210051f65dce76ef7665f05a29bf72bdfd0dc1830e5e524edf075befa367e'),
  ('v2-hs-flow-05', 'flow', 'medium', 'high-school', '(I) Deniz araştırmacıları kıyıdaki plastik parçalarını türlerine göre ayırdı. (II) Parçaların hangi akıntı yönünden geldiği modellendi. (III) Temizleme ekiplerinin çalışacağı koylar bu modele göre seçildi. (IV) Araştırma gemisinin motor bakım saatleri kaydedildi. (V) Seçilen koylarda temizlikten sonra yeni örnekler toplandı.', 'Kıyı araştırmasında akışı bozan cümle hangisidir?', '["I","II","III","V","IV"]'::jsonb, 4, 'IV. cümle gemi motorlarının bakımına geçer; I, II, III ve V plastik kaynaklarını belirleyip temizlik sonucunu izler.', true, 'migration', NULL, '88da3c3e38bbbef587d51673bc24b8eb20bfdc7a0b419b55cfeb72f899617541'),
  ('v2-hs-flow-06', 'flow', 'hard', 'high-school', '(I) Bir dilbilimci, bölgesel ağızlarda kullanılan aynı sözcükleri kaydetti. (II) Sözcüklerin hangi yaş gruplarında ve hangi bağlamlarda söylendiğini sınıflandırdı. (III) Ses kayıtlarını yazıya aktarırken konuşma özelliklerini koruyan işaretler kullandı. (IV) Katılımcıların yazılı dilde tercih ettiği eş anlamlı sözcükler de ayrı bir listede toplandı. (V) Bulgular, sözcük seçiminin yaş ve kullanım bağlamıyla birlikte değiştiğini gösterdi.', 'Bölgesel ağız araştırmasının düşünce akışını bozan cümle hangisidir?', '["I","II","III","V","IV"]'::jsonb, 4, 'IV. cümle katılımcıların yazılı dil tercihlerine geçer; I, II, III ve V ise sözlü ağız verilerinin kaydı, sınıflandırılması, aktarımı ve yorumlanması zincirini sürdürür.', true, 'migration', NULL, 'c2a84396da65c8332336456117594038b092c6833099be88e2d44e931b56578c'),
  ('v2-hs-flow-07', 'flow', 'medium', 'high-school', '(I) Gökbilim ekibi, teleskop görüntülerindeki parlaklık değerlerini kalibre etti. (II) Farklı gecelerde alınan görüntüler aynı ölçekte birleştirildi. (III) Parlaklığı değişen yıldız adayları için zaman çizelgesi çıkarıldı. (IV) Görüntülerin arşivlendiği klasör adları gözlem tarihlerini gösterecek biçimde standartlaştırıldı. (V) Adayların gerçekten değişken olup olmadığı yeni gözlemlerle sınandı.', 'Değişken yıldız adaylarını belirleme çalışmasında akışı bozan cümle hangisidir?', '["I","II","III","V","IV"]'::jsonb, 4, 'IV. cümle arşiv düzenlemesini anlatır; I, II, III ve V ise görüntüleri kalibre edip birleştirme, adayları belirleme ve yeni gözlemle sınama sürecini kurar.', true, 'migration', NULL, '5329a5a841db44a14406f6e055f7f90664394630babcc557cdb1155c03459ed7'),
  ('v2-hs-flow-08', 'flow', 'medium', 'high-school', '(I) Bir hukuk tarihçisi, eski mahkeme kararlarındaki kavramları dönem sözlükleriyle karşılaştırdı. (II) Aynı kavramın farklı yıllardaki kullanımını karar gerekçeleriyle birlikte inceledi. (III) Değişimin, mevzuat ve toplumsal tartışmalarla hangi noktalarda kesiştiğini haritaladı. (IV) Karar metinlerinin tarandığı arşivde sayfa kenarlarının ölçüleri de kaydedildi. (V) Çalışma, kavramların anlamının hukuk metinlerinde zamanla yeniden kurulduğunu savundu.', 'Hukuk kavramlarının tarihsel değişimini inceleyen çalışmada düşünce akışını bozan cümle hangisidir?', '["I","II","III","V","IV"]'::jsonb, 4, 'IV. cümle arşivdeki fiziksel sayfa özelliklerine geçer; I, II, III ve V ise kavramların sözlük, karar, mevzuat ve toplumsal bağlam içindeki değişimini izleyip sonuca bağlar.', true, 'migration', NULL, '208471c05433d3c3b7264e8bfecd98dea8c74afaa271b6ccaf6a437d33056ac4'),
  ('v2-hs-flow-09', 'flow', 'medium', 'high-school', '(I) İklim araştırmacıları, şehir içindeki ısı adası ölçümlerini mahalle bazında ayırdı. (II) Beton yüzey oranı ve ağaç örtüsü haritaları bu ölçümlere eklendi. (III) Gece sıcaklıklarının gündüze göre daha yavaş düştüğü bölgeler belirlendi. (IV) Mahallelerdeki yağmur suyu giderlerinin çapları da ayrı bir çizelgede listelendi. (V) Bulgular, serinletme yatırımlarının yalnızca gündüz sıcaklıklarına göre planlanamayacağını gösterdi.', 'Şehir ısı adası verilerinin yorumlandığı çalışmada düşünce akışını bozan cümle hangisidir?', '["I","II","III","V","IV"]'::jsonb, 4, 'IV. cümle yağmur suyu giderlerinin fiziksel özelliklerine geçer; I, II, III ve V ise ısı ölçümlerini arazi örtüsü ve gece-gündüz farkıyla ilişkilendirerek yatırım sonucuna ilerler.', true, 'migration', NULL, '12600e6d5f6a6e1c567d6f11a1a9f6e4fd44eb51ca0bc56d410b32d5b988dbbc');
